// Avtomatik hazırlanıb; api/_snippets.js bunları AI-yə getmədən cavab kimi göndərir.
export default [
  {"id": "sql-01-1", "lang": "sql", "level": 1, "title": "Cədvəl düzəltmək və məlumat əlavə etmək", "keywords": ["create table", "insert", "cədvəl yaz", "cədvəl düzəlt", "tablo oluştur", "создать таблицу", "ilk sql", "ilk sorğu", "first query", "insert into"], "code": "-- İlk SQL nümunəsi: cədvəl, məlumat və sorğu\nCREATE TABLE telebe (\n  id INTEGER PRIMARY KEY,\n  ad TEXT,\n  yas INTEGER\n);\n\nINSERT INTO telebe (ad, yas) VALUES ('Aysel', 17);\nINSERT INTO telebe (ad, yas) VALUES ('Elvin', 18);\nINSERT INTO telebe (ad, yas) VALUES ('Nigar', 16);\n\nSELECT * FROM telebe;\n"},
  {"id": "sql-01-2", "lang": "sql", "level": 1, "title": "SELECT ilə bütün məlumatları oxumaq", "keywords": ["select", "select *", "bütün sətirlər", "məlumat oxu", "sorgu", "выбрать все", "select all", "hamısını göstər", "cədvəli göstər"], "code": "CREATE TABLE olke (id INTEGER PRIMARY KEY, ad TEXT, paytaxt TEXT);\n\nINSERT INTO olke (ad, paytaxt) VALUES\n  ('Azərbaycan', 'Bakı'),\n  ('Türkiyə', 'Ankara'),\n  ('Gürcüstan', 'Tbilisi'),\n  ('Qazaxıstan', 'Astana');\n\n-- Bütün sütun və sətirlər\nSELECT * FROM olke;\n"},
  {"id": "sql-01-3", "lang": "sql", "level": 1, "title": "Bir neçə sətri bir dəfəyə əlavə etmək", "keywords": ["insert çoxlu", "multiple insert", "birdən çox sətir", "toplu əlavə", "вставка нескольких строк", "values", "əlavə et", "data əlavə"], "code": "CREATE TABLE mehsul (\n  id INTEGER PRIMARY KEY,\n  ad TEXT,\n  qiymet REAL\n);\n\nINSERT INTO mehsul (ad, qiymet) VALUES\n  ('Kitab', 12.5),\n  ('Qələm', 1.2),\n  ('Dəftər', 3.0),\n  ('Çanta', 35.0);\n\nSELECT COUNT(*) AS say FROM mehsul;\nSELECT * FROM mehsul;\n"},
  {"id": "sql-01-4", "lang": "sql", "level": 1, "title": "Sütun adlarını seçmək və ləqəb vermək", "keywords": ["select sütun", "alias", "as", "ləqəb", "sütun seç", "column alias", "выбрать столбцы", "psevdonim", "ad dəyiş"], "code": "CREATE TABLE isci (id INTEGER PRIMARY KEY, ad TEXT, soyad TEXT, maas REAL);\nINSERT INTO isci (ad, soyad, maas) VALUES\n  ('Murad', 'Əliyev', 1500),\n  ('Leyla', 'Həsənova', 1800),\n  ('Zaur', 'Quliyev', 1200);\n\nSELECT ad, soyad FROM isci;\nSELECT ad AS \"İşçi\", maas AS \"Maaş\" FROM isci;\nSELECT ad || ' ' || soyad AS tam_ad, maas * 12 AS illik_maas FROM isci;\n"},
  {"id": "sql-01-5", "lang": "sql", "level": 1, "title": "Hesab əməlləri SELECT ilə", "keywords": ["select hesab", "sql hesablama", "toplama çıxma", "calculator sql", "арифметика sql", "riyazi əməllər", "expression", "2+2", "mathematical"], "code": "-- SELECT cədvəl olmadan da hesablaya bilər\nSELECT 2 + 3 AS cem;\nSELECT 10 - 4 AS ferq, 6 * 7 AS hasil, 22 / 7 AS tam_bolme, 22 / 7.0 AS onluq, 22 % 7 AS qaliq;\nSELECT 'Salam' || ', ' || 'dünya!' AS metn;\nSELECT ABS(-15) AS mutleq, ROUND(3.14159, 2) AS yuvarlaq, UPPER('sql') AS boyuk;\n"},
  {"id": "sql-02-1", "lang": "sql", "level": 2, "title": "WHERE ilə filtr", "keywords": ["where", "filtr", "şərt", "filter", "условие where", "süz", "filtrləmə", "şərtlə seç", "where clause", "şərtli sorğu"], "code": "CREATE TABLE telebe (id INTEGER PRIMARY KEY, ad TEXT, sinif INTEGER, bal INTEGER);\nINSERT INTO telebe (ad, sinif, bal) VALUES\n  ('Aysel', 11, 95), ('Elvin', 10, 72), ('Nigar', 11, 88),\n  ('Murad', 9, 60), ('Leyla', 10, 91), ('Zaur', 11, 45);\n\nSELECT * FROM telebe WHERE sinif = 11;\nSELECT ad, bal FROM telebe WHERE bal >= 90;\nSELECT ad FROM telebe WHERE sinif = 11 AND bal > 50;\nSELECT ad FROM telebe WHERE sinif = 9 OR bal < 50;\n"},
  {"id": "sql-02-2", "lang": "sql", "level": 2, "title": "ORDER BY ilə sıralama", "keywords": ["order by", "sıralama", "sort", "asc desc", "sırala", "сортировка", "azalan", "artan", "ən yüksək bal", "sıralı siyahı"], "code": "CREATE TABLE oyun (id INTEGER PRIMARY KEY, ad TEXT, xal INTEGER);\nINSERT INTO oyun (ad, xal) VALUES ('Aysel', 320), ('Murad', 150), ('Nigar', 480), ('Elvin', 150), ('Leyla', 275);\n\nSELECT * FROM oyun ORDER BY xal DESC;\nSELECT * FROM oyun ORDER BY xal ASC, ad ASC;\nSELECT ad FROM oyun ORDER BY ad;\n"},
  {"id": "sql-02-3", "lang": "sql", "level": 2, "title": "LIMIT və OFFSET", "keywords": ["limit", "offset", "ilk 3", "top 3", "səhifələmə", "pagination", "ограничить", "ilk nəticələr", "first rows", "top n"], "code": "CREATE TABLE kitab (id INTEGER PRIMARY KEY, ad TEXT, sehife INTEGER);\nINSERT INTO kitab (ad, sehife) VALUES\n  ('A', 120), ('B', 340), ('C', 90), ('D', 510), ('E', 275), ('F', 60), ('G', 410);\n\n-- Ən qalın 3 kitab\nSELECT * FROM kitab ORDER BY sehife DESC LIMIT 3;\n-- Səhifələmə: 2-ci səhifə (hər səhifədə 3 sətir)\nSELECT * FROM kitab ORDER BY id LIMIT 3 OFFSET 3;\n"},
  {"id": "sql-02-4", "lang": "sql", "level": 2, "title": "DISTINCT ilə təkrarsız dəyərlər", "keywords": ["distinct", "unikal", "təkrarsız", "unique values", "повторы", "təkrar sil", "fərqli dəyərlər", "distinct select"], "code": "CREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri TEXT, seher TEXT);\nINSERT INTO sifaris (musteri, seher) VALUES\n  ('Aysel', 'Bakı'), ('Murad', 'Gəncə'), ('Nigar', 'Bakı'),\n  ('Elvin', 'Şəki'), ('Leyla', 'Gəncə'), ('Zaur', 'Bakı');\n\nSELECT seher FROM sifaris;\nSELECT DISTINCT seher FROM sifaris;\nSELECT COUNT(DISTINCT seher) AS seher_sayi FROM sifaris;\n"},
  {"id": "sql-02-5", "lang": "sql", "level": 2, "title": "Hesablanmış sütun və CASE", "keywords": ["case when", "hesablanmış sütun", "computed column", "şərtli dəyər", "условное выражение", "if else sql", "kateqoriya", "bal qiymətləndirmə"], "code": "CREATE TABLE imtahan (ad TEXT, bal INTEGER);\nINSERT INTO imtahan VALUES ('Aysel', 95), ('Elvin', 72), ('Nigar', 58), ('Murad', 83), ('Zaur', 41);\n\nSELECT ad, bal,\n  CASE\n    WHEN bal >= 90 THEN 'əla'\n    WHEN bal >= 70 THEN 'yaxşı'\n    WHEN bal >= 50 THEN 'kafi'\n    ELSE 'qeyri-kafi'\n  END AS qiymet\nFROM imtahan\nORDER BY bal DESC;\n"},
  {"id": "sql-03-1", "lang": "sql", "level": 3, "title": "LIKE ilə mətn axtarışı", "keywords": ["like", "axtarış", "mətn axtar", "pattern", "wildcard", "%", "поиск по шаблону", "ilə başlayan", "contains", "içində var"], "code": "CREATE TABLE mehsul (id INTEGER PRIMARY KEY, ad TEXT);\nINSERT INTO mehsul (ad) VALUES ('Alma şirəsi'), ('Armud şirəsi'), ('Nar'), ('Albalı mürəbbəsi'), ('Şirin çay');\n\nSELECT * FROM mehsul WHERE ad LIKE 'Al%';       -- Al ilə başlayır\nSELECT * FROM mehsul WHERE ad LIKE '%şirə%';    -- içində şirə var\nSELECT * FROM mehsul WHERE ad LIKE '___';       -- düz 3 hərf\nSELECT * FROM mehsul WHERE ad NOT LIKE '%i%';\n"},
  {"id": "sql-03-2", "lang": "sql", "level": 3, "title": "IN və BETWEEN", "keywords": ["in", "between", "aralıq", "range", "siyahıda", "dəyər aralığı", "диапазон", "между", "in operatoru", "tarix aralığı"], "code": "CREATE TABLE mehsul (ad TEXT, kateqoriya TEXT, qiymet REAL);\nINSERT INTO mehsul VALUES\n  ('Alma', 'meyvə', 2.5), ('Pomidor', 'tərəvəz', 3.2), ('Süd', 'süd', 2.0),\n  ('Pendir', 'süd', 9.5), ('Armud', 'meyvə', 4.0), ('Xiyar', 'tərəvəz', 1.8);\n\nSELECT * FROM mehsul WHERE kateqoriya IN ('meyvə', 'süd');\nSELECT * FROM mehsul WHERE kateqoriya NOT IN ('süd');\nSELECT * FROM mehsul WHERE qiymet BETWEEN 2 AND 4;\n"},
  {"id": "sql-03-3", "lang": "sql", "level": 3, "title": "NULL dəyərləri", "keywords": ["null", "is null", "boş dəyər", "coalesce", "ifnull", "пустые значения", "nullif", "boşluq", "yoxdur", "null yoxla"], "code": "CREATE TABLE telefon (ad TEXT, nomre TEXT);\nINSERT INTO telefon VALUES ('Aysel', '050-111-11-11'), ('Murad', NULL), ('Nigar', '055-222-22-22'), ('Elvin', NULL);\n\nSELECT * FROM telefon WHERE nomre IS NULL;\nSELECT * FROM telefon WHERE nomre IS NOT NULL;\nSELECT ad, COALESCE(nomre, 'nömrə yoxdur') AS nomre FROM telefon;\nSELECT ad, IFNULL(nomre, '-') AS nomre FROM telefon ORDER BY ad;\n"},
  {"id": "sql-03-4", "lang": "sql", "level": 3, "title": "Mətn funksiyaları", "keywords": ["mətn funksiyaları", "string functions", "upper lower", "length", "substr", "replace", "trim", "instr", "строковые функции sql", "mətn emalı"], "code": "SELECT UPPER('nibras') AS boyuk, LOWER('KOD') AS kicik;\nSELECT LENGTH('Azərbaycan') AS uzunluq;\nSELECT SUBSTR('Azərbaycan', 1, 4) AS ilk4, SUBSTR('Azərbaycan', -4) AS son4;\nSELECT REPLACE('salam dünya', 'dünya', 'SQL') AS yeni;\nSELECT TRIM('   boşluqlar   ') AS temiz, INSTR('salam', 'l') AS yer;\nSELECT 'Ad: ' || 'Elvin' || ', yaş: ' || 21 AS birlesme;\n"},
  {"id": "sql-03-5", "lang": "sql", "level": 3, "title": "Say funksiyaları", "keywords": ["say funksiyaları", "numeric functions", "round", "abs", "max min", "tam hissə", "числовые функции", "yuvarlaqlaşdır", "random", "riyazi funksiyalar"], "code": "SELECT ROUND(3.14159, 3) AS pi, ROUND(2.5) AS r1, ROUND(-2.5) AS r2;\nSELECT ABS(-42) AS mutleq, MAX(3, 9, 4) AS en_boyuk, MIN(3, 9, 4) AS en_kicik;\nSELECT CAST(7.9 AS INTEGER) AS tam, 7 / 2 AS tam_bolme, 7 / 2.0 AS onluq;\nSELECT TYPEOF(1), TYPEOF(1.5), TYPEOF('a'), TYPEOF(NULL);\nSELECT 17 % 5 AS qaliq, -7 % 3 AS menfi_qaliq, 2 * (3 + 4) AS moterize;\n"},
  {"id": "sql-04-1", "lang": "sql", "level": 4, "title": "COUNT, SUM, AVG, MIN, MAX", "keywords": ["count", "sum", "avg", "min max", "aqreqat", "aggregate", "агрегатные функции", "toplam", "ortalama", "say", "cəm", "statistika"], "code": "CREATE TABLE satis (id INTEGER PRIMARY KEY, mehsul TEXT, say INTEGER, qiymet REAL);\nINSERT INTO satis (mehsul, say, qiymet) VALUES\n  ('Kitab', 3, 12.5), ('Qələm', 10, 1.2), ('Dəftər', 5, 3.0), ('Çanta', 1, 35.0), ('Kitab', 2, 12.5);\n\nSELECT COUNT(*) AS setir_sayi FROM satis;\nSELECT SUM(say) AS cemi_say, ROUND(AVG(qiymet), 2) AS orta_qiymet FROM satis;\nSELECT MIN(qiymet) AS ucuz, MAX(qiymet) AS bahali FROM satis;\nSELECT SUM(say * qiymet) AS gelir FROM satis;\n"},
  {"id": "sql-04-2", "lang": "sql", "level": 4, "title": "Ortalama və yuvarlaq nəticələr", "keywords": ["ortalama", "orta bal", "average", "round avg", "sinif ortalaması", "средний балл", "ortalamayı tap", "bal ortalaması", "statistika sql"], "code": "CREATE TABLE bal (telebe TEXT, fenn TEXT, deyer INTEGER);\nINSERT INTO bal VALUES\n  ('Aysel', 'riyaziyyat', 95), ('Aysel', 'fizika', 88), ('Aysel', 'kimya', 92),\n  ('Elvin', 'riyaziyyat', 70), ('Elvin', 'fizika', 65), ('Elvin', 'kimya', 80);\n\nSELECT ROUND(AVG(deyer), 1) AS umumi_orta FROM bal;\nSELECT telebe, ROUND(AVG(deyer), 1) AS orta FROM bal GROUP BY telebe;\nSELECT fenn, MAX(deyer) - MIN(deyer) AS ferq FROM bal GROUP BY fenn;\n"},
  {"id": "sql-04-3", "lang": "sql", "level": 4, "title": "COUNT və şərtli say", "keywords": ["count where", "şərtli say", "nə qədər", "how many", "сколько", "sayını tap", "sətir sayı", "count if", "sum case"], "code": "CREATE TABLE tapsiriq (id INTEGER PRIMARY KEY, ad TEXT, bitib INTEGER);\nINSERT INTO tapsiriq (ad, bitib) VALUES\n  ('Dərs oxu', 1), ('Kitab oxu', 0), ('Məşq et', 1), ('Otağı yığ', 0), ('Layihə', 0);\n\nSELECT COUNT(*) AS hamisi FROM tapsiriq;\nSELECT COUNT(*) AS bitmis FROM tapsiriq WHERE bitib = 1;\nSELECT SUM(bitib = 1) AS bitmis, SUM(bitib = 0) AS qalan FROM tapsiriq;\nSELECT ROUND(100.0 * SUM(bitib) / COUNT(*), 1) || '%' AS faiz FROM tapsiriq;\n"},
  {"id": "sql-04-4", "lang": "sql", "level": 4, "title": "Cəm və ümumi məbləğ", "keywords": ["sum", "cəm", "ümumi məbləğ", "total", "gəlir", "income", "expense", "xərc", "büdcə", "бюджет", "общая сумма", "balans hesabla"], "code": "CREATE TABLE emeliyyat (id INTEGER PRIMARY KEY, tip TEXT, mebleg REAL);\nINSERT INTO emeliyyat (tip, mebleg) VALUES\n  ('gəlir', 1500), ('xərc', 300), ('xərc', 120.5), ('gəlir', 400), ('xərc', 80);\n\nSELECT SUM(mebleg) FILTER (WHERE tip = 'gəlir') AS gelir FROM emeliyyat;\nSELECT SUM(CASE WHEN tip = 'xərc' THEN mebleg ELSE 0 END) AS xerc FROM emeliyyat;\nSELECT SUM(CASE WHEN tip = 'gəlir' THEN mebleg ELSE -mebleg END) AS qaliq FROM emeliyyat;\n"},
  {"id": "sql-04-5", "lang": "sql", "level": 4, "title": "Ən böyük və ən kiçik dəyəri tapmaq", "keywords": ["max min", "ən böyük", "ən kiçik", "ən bahalı", "ən ucuz", "самый большой", "maksimum minimum", "rekord", "top 1"], "code": "CREATE TABLE sehir (ad TEXT, ehali INTEGER);\nINSERT INTO sehir VALUES ('Bakı', 2300000), ('Gəncə', 335000), ('Sumqayıt', 345000), ('Mingəçevir', 100000), ('Şəki', 68000);\n\nSELECT MAX(ehali) AS en_boyuk, MIN(ehali) AS en_kicik FROM sehir;\nSELECT ad FROM sehir ORDER BY ehali DESC LIMIT 1;\nSELECT ad FROM sehir WHERE ehali = (SELECT MIN(ehali) FROM sehir);\nSELECT ad, ehali FROM sehir WHERE ehali > (SELECT AVG(ehali) FROM sehir);\n"},
  {"id": "sql-05-1", "lang": "sql", "level": 5, "title": "GROUP BY", "keywords": ["group by", "qruplaşdır", "qrup", "группировка", "kateqoriyaya görə", "hər kateqoriya üçün", "hesabat", "report", "qrup üzrə say"], "code": "CREATE TABLE sifaris (id INTEGER PRIMARY KEY, seher TEXT, mebleg REAL);\nINSERT INTO sifaris (seher, mebleg) VALUES\n  ('Bakı', 120), ('Gəncə', 80), ('Bakı', 200), ('Şəki', 45), ('Gəncə', 150), ('Bakı', 60);\n\nSELECT seher, COUNT(*) AS say, SUM(mebleg) AS cem, ROUND(AVG(mebleg), 1) AS orta\nFROM sifaris\nGROUP BY seher\nORDER BY cem DESC;\n"},
  {"id": "sql-05-2", "lang": "sql", "level": 5, "title": "HAVING ilə qrup filtri", "keywords": ["having", "qrup filtri", "group filter", "фильтр групп", "qrupdan sonra şərt", "having count", "aqreqat şərt", "təkrarlananlar"], "code": "CREATE TABLE musteri_sifaris (musteri TEXT, mebleg REAL);\nINSERT INTO musteri_sifaris VALUES\n  ('Aysel', 50), ('Aysel', 70), ('Murad', 30), ('Nigar', 120), ('Nigar', 40), ('Nigar', 90), ('Elvin', 20);\n\n-- 2-dən çox sifariş verən müştərilər\nSELECT musteri, COUNT(*) AS say, SUM(mebleg) AS cem\nFROM musteri_sifaris\nGROUP BY musteri\nHAVING COUNT(*) >= 2\nORDER BY cem DESC;\n"},
  {"id": "sql-05-3", "lang": "sql", "level": 5, "title": "Bir neçə sütunla qruplaşdırma", "keywords": ["group by iki sütun", "multiple group", "çoxsütunlu qrup", "qrup birləşməsi", "сводная таблица", "pivot", "il və ay üzrə", "cross tab"], "code": "CREATE TABLE satis (il INTEGER, ay INTEGER, mehsul TEXT, mebleg REAL);\nINSERT INTO satis VALUES\n  (2025, 1, 'A', 100), (2025, 1, 'B', 50), (2025, 2, 'A', 80),\n  (2026, 1, 'A', 120), (2026, 1, 'B', 90), (2026, 2, 'B', 60);\n\nSELECT il, ay, SUM(mebleg) AS cem FROM satis GROUP BY il, ay ORDER BY il, ay;\nSELECT mehsul,\n  SUM(CASE WHEN il = 2025 THEN mebleg ELSE 0 END) AS y2025,\n  SUM(CASE WHEN il = 2026 THEN mebleg ELSE 0 END) AS y2026\nFROM satis GROUP BY mehsul;\n"},
  {"id": "sql-05-4", "lang": "sql", "level": 5, "title": "Təkrarlananları tapmaq", "keywords": ["təkrarlananlar", "duplicates", "dublikat", "tekrar eden", "найти дубликаты", "eyni dəyər", "repeated values", "unikal olmayan", "say > 1"], "code": "CREATE TABLE email_siyahi (id INTEGER PRIMARY KEY, email TEXT);\nINSERT INTO email_siyahi (email) VALUES\n  ('a@mail.az'), ('b@mail.az'), ('a@mail.az'), ('c@mail.az'), ('b@mail.az'), ('a@mail.az');\n\nSELECT email, COUNT(*) AS say\nFROM email_siyahi\nGROUP BY email\nHAVING COUNT(*) > 1;\n\n-- Hər təkrarın yalnız ilk id-sini saxlamaq üçün\nSELECT MIN(id) AS saxla, email FROM email_siyahi GROUP BY email;\n"},
  {"id": "sql-05-5", "lang": "sql", "level": 5, "title": "Hər qrupda ortalama və çox/az", "keywords": ["qrup ortalama", "faiz", "nisbət", "ratio", "процент", "group avg", "əhali", "kateqoriya payı", "payı hesabla"], "code": "CREATE TABLE xerc (kateqoriya TEXT, mebleg REAL);\nINSERT INTO xerc VALUES ('qida', 300), ('nəqliyyat', 80), ('qida', 220), ('əyləncə', 60), ('nəqliyyat', 70), ('kommunal', 150);\n\nSELECT kateqoriya,\n  SUM(mebleg) AS cem,\n  ROUND(100.0 * SUM(mebleg) / (SELECT SUM(mebleg) FROM xerc), 1) AS faiz\nFROM xerc\nGROUP BY kateqoriya\nORDER BY cem DESC;\n"},
  {"id": "sql-06-1", "lang": "sql", "level": 6, "title": "UPDATE ilə məlumatı dəyişmək", "keywords": ["update", "dəyişdir", "yenilə", "set", "güncelle", "обновить", "məlumat yenilə", "update where", "qiyməti artır", "maaş artımı"], "code": "CREATE TABLE isci (id INTEGER PRIMARY KEY, ad TEXT, vezife TEXT, maas REAL);\nINSERT INTO isci (ad, vezife, maas) VALUES\n  ('Murad', 'tərtibatçı', 1500), ('Leyla', 'dizayner', 1300), ('Zaur', 'tərtibatçı', 1600);\n\n-- Yalnız bir sətri dəyişir\nUPDATE isci SET maas = 1700 WHERE ad = 'Leyla';\n-- Bir neçə sətri dəyişir: tərtibatçılara 10% artım\nUPDATE isci SET maas = maas * 1.10 WHERE vezife = 'tərtibatçı';\n\nSELECT ad, vezife, ROUND(maas, 2) AS maas FROM isci;\n"},
  {"id": "sql-06-2", "lang": "sql", "level": 6, "title": "DELETE ilə sətir silmək", "keywords": ["delete", "sil", "remove", "удалить", "sətir sil", "məlumat sil", "delete where", "təmizlə", "clear table", "truncate"], "code": "CREATE TABLE mesaj (id INTEGER PRIMARY KEY, metn TEXT, oxunub INTEGER DEFAULT 0);\nINSERT INTO mesaj (metn, oxunub) VALUES ('Salam', 1), ('Toplantı', 0), ('Reklam', 1), ('Xatırlatma', 0), ('Spam', 1);\n\nSELECT COUNT(*) AS evvel FROM mesaj;\nDELETE FROM mesaj WHERE metn = 'Spam';           -- bir sətir\nDELETE FROM mesaj WHERE oxunub = 1;              -- oxunmuşları sil\nSELECT COUNT(*) AS sonra FROM mesaj;\nSELECT * FROM mesaj;\n-- DELETE FROM mesaj;  (WHERE olmasa bütün sətirlər silinir!)\n"},
  {"id": "sql-06-3", "lang": "sql", "level": 6, "title": "ALTER TABLE: sütun əlavə və ad dəyiş", "keywords": ["alter table", "sütun əlavə", "add column", "rename", "ad dəyiş", "изменить таблицу", "drop column", "cədvəli dəyiş", "sxem dəyiş"], "code": "CREATE TABLE telebe (id INTEGER PRIMARY KEY, ad TEXT);\nINSERT INTO telebe (ad) VALUES ('Aysel'), ('Elvin');\n\nALTER TABLE telebe ADD COLUMN sinif INTEGER DEFAULT 1;\nUPDATE telebe SET sinif = 10 WHERE ad = 'Aysel';\nALTER TABLE telebe RENAME COLUMN sinif TO sinif_nomresi;\nALTER TABLE telebe RENAME TO telebeler;\n\nSELECT * FROM telebeler;\nPRAGMA table_info(telebeler);\n"},
  {"id": "sql-06-4", "lang": "sql", "level": 6, "title": "Cədvəldən kopya və INSERT SELECT", "keywords": ["insert select", "kopyala", "copy table", "arxiv", "backup", "архив", "cədvəl kopyası", "create table as", "nüsxə", "köçürmə"], "code": "CREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri TEXT, mebleg REAL, bagli INTEGER);\nINSERT INTO sifaris (musteri, mebleg, bagli) VALUES ('Aysel', 50, 1), ('Murad', 20, 0), ('Nigar', 90, 1), ('Elvin', 35, 1);\n\nCREATE TABLE arxiv AS SELECT * FROM sifaris WHERE bagli = 1;\nCREATE TABLE gelir_hesabati (musteri TEXT, mebleg REAL);\nINSERT INTO gelir_hesabati SELECT musteri, mebleg FROM sifaris WHERE mebleg >= 50;\nDELETE FROM sifaris WHERE bagli = 1;\n\nSELECT 'sifaris' AS cedvel, COUNT(*) AS say FROM sifaris\nUNION ALL SELECT 'arxiv', COUNT(*) FROM arxiv\nUNION ALL SELECT 'gelir_hesabati', COUNT(*) FROM gelir_hesabati;\n"},
  {"id": "sql-06-5", "lang": "sql", "level": 6, "title": "Cədvəli silmək: DROP TABLE", "keywords": ["drop table", "cədvəl sil", "if exists", "удалить таблицу", "cədvəl yoxla", "sxem", "təmiz başlanğıc", "reset", "yenidən qur"], "code": "DROP TABLE IF EXISTS test;          -- cədvəl yoxdursa xəta vermir\nCREATE TABLE test (id INTEGER PRIMARY KEY, ad TEXT);\nINSERT INTO test (ad) VALUES ('bir'), ('iki');\nSELECT COUNT(*) AS evvel FROM test;\n\nDROP TABLE test;\nSELECT name FROM sqlite_master WHERE type = 'table' AND name = 'test';   -- boş cavab\nCREATE TABLE IF NOT EXISTS test (id INTEGER);\nSELECT name FROM sqlite_master WHERE type = 'table';\n"},
  {"id": "sql-07-1", "lang": "sql", "level": 7, "title": "PRIMARY KEY, NOT NULL və UNIQUE", "keywords": ["primary key", "not null", "unique", "məhdudiyyət", "constraint", "ограничения", "açar sahə", "unikal", "boş ola bilməz", "sütun qaydaları"], "code": "CREATE TABLE istifadeci (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  login TEXT NOT NULL UNIQUE,\n  email TEXT NOT NULL UNIQUE,\n  ad TEXT NOT NULL\n);\n\nINSERT INTO istifadeci (login, email, ad) VALUES ('aysel', 'aysel@mail.az', 'Aysel');\nINSERT INTO istifadeci (login, email, ad) VALUES ('murad', 'murad@mail.az', 'Murad');\n-- Təkrar login xətasını görmək üçün INSERT OR IGNORE\nINSERT OR IGNORE INTO istifadeci (login, email, ad) VALUES ('aysel', 'basqa@mail.az', 'Təkrar');\n\nSELECT * FROM istifadeci;\nSELECT changes() AS son_deyisen_setir;\n"},
  {"id": "sql-07-2", "lang": "sql", "level": 7, "title": "DEFAULT və CHECK", "keywords": ["default", "check", "standart dəyər", "yoxlama şərti", "значение по умолчанию", "check constraint", "bal 0-100", "qayda", "validation sql"], "code": "CREATE TABLE imtahan (\n  id INTEGER PRIMARY KEY,\n  telebe TEXT NOT NULL,\n  bal INTEGER NOT NULL CHECK (bal BETWEEN 0 AND 100),\n  status TEXT NOT NULL DEFAULT 'gözləyir' CHECK (status IN ('gözləyir', 'keçdi', 'kəsildi'))\n);\n\nINSERT INTO imtahan (telebe, bal) VALUES ('Aysel', 95);\nINSERT INTO imtahan (telebe, bal, status) VALUES ('Elvin', 40, 'kəsildi');\nINSERT OR IGNORE INTO imtahan (telebe, bal) VALUES ('Səhv', 150);   -- CHECK pozulur, atlanır\n\nSELECT * FROM imtahan;\n"},
  {"id": "sql-07-3", "lang": "sql", "level": 7, "title": "Məlumat tipləri və CAST", "keywords": ["məlumat tipləri", "data types", "cast", "typeof", "integer text real", "типы данных", "tip çevirmə sql", "type affinity", "mətn rəqəm"], "code": "CREATE TABLE tipler (a INTEGER, b REAL, c TEXT, d BLOB, e NUMERIC);\nINSERT INTO tipler VALUES (42, 3.14, 'salam', x'48656C6C6F', '15');\n\nSELECT typeof(a), typeof(b), typeof(c), typeof(d), typeof(e) FROM tipler;\nSELECT CAST('123' AS INTEGER) + 1 AS ededir, CAST(5 AS TEXT) || '0' AS metindir;\nSELECT CAST(3.99 AS INTEGER) AS kəsilmiş, CAST('abc' AS INTEGER) AS sifir;\nSELECT hex(d) AS hex, length(d) AS bayt FROM tipler;\n"},
  {"id": "sql-07-4", "lang": "sql", "level": 7, "title": "Avtomatik artan ID və rowid", "keywords": ["autoincrement", "auto increment", "id", "rowid", "last_insert_rowid", "avtomatik nömrə", "автоинкремент", "sıra nömrəsi", "ardıcıl id"], "code": "CREATE TABLE bilet (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sahib TEXT NOT NULL\n);\n\nINSERT INTO bilet (sahib) VALUES ('Aysel');\nSELECT last_insert_rowid() AS son_id;\nINSERT INTO bilet (sahib) VALUES ('Murad'), ('Nigar');\nDELETE FROM bilet WHERE id = 3;\nINSERT INTO bilet (sahib) VALUES ('Elvin');     -- AUTOINCREMENT köhnə id-ni təkrar vermir\n\nSELECT * FROM bilet;\nSELECT name, seq FROM sqlite_sequence;\n"},
  {"id": "sql-07-5", "lang": "sql", "level": 7, "title": "Cədvəl səviyyəsində məhdudiyyətlər", "keywords": ["composite key", "mürəkkəb açar", "table constraint", "birgə unikal", "çoxsütunlu açar", "составной ключ", "primary key iki sütun", "unikal cüt"], "code": "CREATE TABLE qeydiyyat (\n  telebe_id INTEGER NOT NULL,\n  kurs_id INTEGER NOT NULL,\n  tarix TEXT NOT NULL DEFAULT '2026-09-01',\n  PRIMARY KEY (telebe_id, kurs_id)\n);\n\nINSERT INTO qeydiyyat (telebe_id, kurs_id) VALUES (1, 10), (1, 20), (2, 10);\nINSERT OR IGNORE INTO qeydiyyat (telebe_id, kurs_id) VALUES (1, 10);    -- eyni cüt təkrar olunmur\n\nSELECT * FROM qeydiyyat ORDER BY telebe_id, kurs_id;\nSELECT telebe_id, COUNT(*) AS kurs_sayi FROM qeydiyyat GROUP BY telebe_id;\n"},
  {"id": "sql-08-1", "lang": "sql", "level": 8, "title": "Tarix və vaxt funksiyaları", "keywords": ["date", "time", "datetime", "strftime", "tarix funksiyaları", "дата и время", "date function", "bu gün", "indi", "tarix formatı", "gün ay il"], "code": "SELECT date('2026-10-03') AS tarix;\nSELECT date('2026-10-03', '+30 days') AS otuz_gun_sonra;\nSELECT date('2026-10-03', '-1 month') AS bir_ay_evvel;\nSELECT date('2026-10-03', 'start of month') AS ayin_evveli, date('2026-10-03', 'start of month', '+1 month', '-1 day') AS ayin_sonu;\nSELECT strftime('%Y', '2026-10-03') AS il, strftime('%m', '2026-10-03') AS ay, strftime('%d', '2026-10-03') AS gun;\nSELECT strftime('%w', '2026-10-03') AS heftenin_gunu;   -- 0 = bazar, 6 = şənbə\nSELECT datetime('2026-10-03 14:30:00', '+2 hours') AS iki_saat_sonra;\n"},
  {"id": "sql-08-2", "lang": "sql", "level": 8, "title": "Tarixlər arası fərq", "keywords": ["tarix fərqi", "julianday", "gün sayı", "days between", "разница дат", "yaş hesabla", "neçə gün qalıb", "vaxt fərqi", "yaş", "doğum günü"], "code": "CREATE TABLE sexs (ad TEXT, dogum TEXT);\nINSERT INTO sexs VALUES ('Aysel', '2008-05-14'), ('Murad', '1995-12-01'), ('Zaur', '1980-02-29');\n\nSELECT ad, dogum,\n  CAST((julianday('2026-10-03') - julianday(dogum)) / 365.25 AS INTEGER) AS yas,\n  CAST(julianday('2026-10-03') - julianday(dogum) AS INTEGER) AS yasadigi_gun\nFROM sexs;\n\nSELECT CAST(julianday('2026-12-31') - julianday('2026-10-03') AS INTEGER) AS ilin_sonuna_gun;\n"},
  {"id": "sql-08-3", "lang": "sql", "level": 8, "title": "Tarixə görə qruplaşdırma", "keywords": ["aylıq hesabat", "monthly report", "tarix qrupla", "strftime group", "il və ay", "satış hesabatı", "отчет по месяцам", "gün üzrə", "aylara görə"], "code": "CREATE TABLE satis (id INTEGER PRIMARY KEY, tarix TEXT, mebleg REAL);\nINSERT INTO satis (tarix, mebleg) VALUES\n  ('2026-01-05', 100), ('2026-01-20', 150), ('2026-02-02', 80),\n  ('2026-02-14', 120), ('2026-02-28', 60), ('2026-03-10', 200);\n\nSELECT strftime('%Y-%m', tarix) AS ay, COUNT(*) AS say, SUM(mebleg) AS cem\nFROM satis\nGROUP BY ay\nORDER BY ay;\n\nSELECT * FROM satis WHERE tarix BETWEEN '2026-02-01' AND '2026-02-28';\n"},
  {"id": "sql-08-4", "lang": "sql", "level": 8, "title": "Son N gün və tarix filtri", "keywords": ["son 7 gün", "last days", "tarix filtri", "date filter", "последние дни", "bu ayın", "bu həftə", "tarixə görə filtr", "aktiv istifadəçilər"], "code": "CREATE TABLE giris (id INTEGER PRIMARY KEY, istifadeci TEXT, vaxt TEXT);\nINSERT INTO giris (istifadeci, vaxt) VALUES\n  ('Aysel', '2026-10-02 09:15:00'), ('Murad', '2026-09-20 18:40:00'),\n  ('Nigar', '2026-10-01 12:00:00'), ('Aysel', '2026-09-29 08:05:00'), ('Zaur', '2026-08-15 21:30:00');\n\n-- Sabit \"bu gün\" (2026-10-03) götürürük ki, nəticə həmişə eyni olsun\nSELECT * FROM giris WHERE vaxt >= datetime('2026-10-03', '-7 days') ORDER BY vaxt DESC;\nSELECT istifadeci, COUNT(*) AS giris_sayi FROM giris WHERE date(vaxt) >= '2026-09-01' GROUP BY istifadeci;\n"},
  {"id": "sql-08-5", "lang": "sql", "level": 8, "title": "Həftənin günləri və CASE", "keywords": ["həftənin günü", "weekday", "gün adı", "bazar ertəsi", "день недели", "strftime %w", "iş günü", "istirahət günü", "gün adlarını çıxar"], "code": "CREATE TABLE tedbir (ad TEXT, tarix TEXT);\nINSERT INTO tedbir VALUES ('Dərs', '2026-10-05'), ('Toplantı', '2026-10-07'), ('Futbol', '2026-10-10'), ('Səfər', '2026-10-11');\n\nSELECT ad, tarix,\n  CASE CAST(strftime('%w', tarix) AS INTEGER)\n    WHEN 0 THEN 'bazar' WHEN 1 THEN 'bazar ertəsi' WHEN 2 THEN 'çərşənbə axşamı'\n    WHEN 3 THEN 'çərşənbə' WHEN 4 THEN 'cümə axşamı' WHEN 5 THEN 'cümə' ELSE 'şənbə'\n  END AS gun_adi,\n  CASE WHEN strftime('%w', tarix) IN ('0', '6') THEN 'istirahət' ELSE 'iş günü' END AS tip\nFROM tedbir ORDER BY tarix;\n"},
  {"id": "sql-09-1", "lang": "sql", "level": 9, "title": "INNER JOIN", "keywords": ["inner join", "join", "birləşdir", "cədvəlləri birləşdir", "соединение", "объединение таблиц", "iki cədvəl", "join nədir", "əlaqəli cədvəllər"], "code": "CREATE TABLE musteri (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri_id INTEGER, mebleg REAL);\nINSERT INTO musteri VALUES (1, 'Aysel'), (2, 'Murad'), (3, 'Nigar');\nINSERT INTO sifaris VALUES (1, 1, 50), (2, 1, 30), (3, 2, 120), (4, 3, 75);\n\nSELECT m.ad, s.id AS sifaris_no, s.mebleg\nFROM sifaris AS s\nINNER JOIN musteri AS m ON m.id = s.musteri_id\nORDER BY m.ad, s.id;\n"},
  {"id": "sql-09-2", "lang": "sql", "level": 9, "title": "JOIN və GROUP BY", "keywords": ["join group by", "müştəri üzrə cəm", "join aqreqat", "hər müştərinin sifariş cəmi", "join ilə hesabat", "сумма по клиентам", "qrup və birləşmə", "sales report"], "code": "CREATE TABLE musteri (id INTEGER PRIMARY KEY, ad TEXT, seher TEXT);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri_id INTEGER, mebleg REAL);\nINSERT INTO musteri VALUES (1, 'Aysel', 'Bakı'), (2, 'Murad', 'Gəncə'), (3, 'Nigar', 'Bakı');\nINSERT INTO sifaris VALUES (1, 1, 50), (2, 1, 30), (3, 2, 120), (4, 3, 75), (5, 3, 25);\n\nSELECT m.ad, COUNT(s.id) AS sifaris_sayi, SUM(s.mebleg) AS cem\nFROM musteri m JOIN sifaris s ON s.musteri_id = m.id\nGROUP BY m.id\nORDER BY cem DESC;\n\nSELECT m.seher, SUM(s.mebleg) AS seher_cemi\nFROM musteri m JOIN sifaris s ON s.musteri_id = m.id\nGROUP BY m.seher;\n"},
  {"id": "sql-09-3", "lang": "sql", "level": 9, "title": "Üç cədvəli birləşdirmək", "keywords": ["üç cədvəl", "three table join", "çoxlu join", "many to many", "multiple joins", "соединение трех таблиц", "tələbə kurs müəllim", "əlaqə cədvəli"], "code": "CREATE TABLE telebe (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE kurs (id INTEGER PRIMARY KEY, ad TEXT, muellim TEXT);\nCREATE TABLE yazilma (telebe_id INTEGER, kurs_id INTEGER, bal INTEGER);\nINSERT INTO telebe VALUES (1, 'Aysel'), (2, 'Elvin'), (3, 'Nigar');\nINSERT INTO kurs VALUES (10, 'Python', 'Murad'), (20, 'SQL', 'Leyla');\nINSERT INTO yazilma VALUES (1, 10, 90), (1, 20, 85), (2, 10, 70), (3, 20, 95);\n\nSELECT t.ad AS telebe, k.ad AS kurs, k.muellim, y.bal\nFROM yazilma y\nJOIN telebe t ON t.id = y.telebe_id\nJOIN kurs k ON k.id = y.kurs_id\nORDER BY t.ad, k.ad;\n"},
  {"id": "sql-09-4", "lang": "sql", "level": 9, "title": "Join ilə filtr və sıralama", "keywords": ["join where", "şərtli join", "join order by", "kateqoriya adı", "məhsul və kateqoriya", "товары и категории", "ad ilə göstər", "id əvəzinə ad"], "code": "CREATE TABLE kateqoriya (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE mehsul (id INTEGER PRIMARY KEY, ad TEXT, qiymet REAL, kat_id INTEGER);\nINSERT INTO kateqoriya VALUES (1, 'Meyvə'), (2, 'Süd məhsulları'), (3, 'İçki');\nINSERT INTO mehsul VALUES\n  (1, 'Alma', 2.5, 1), (2, 'Armud', 3.0, 1), (3, 'Süd', 2.2, 2),\n  (4, 'Pendir', 9.8, 2), (5, 'Şirə', 3.5, 3);\n\nSELECT m.ad AS mehsul, k.ad AS kateqoriya, m.qiymet\nFROM mehsul m\nJOIN kateqoriya k ON k.id = m.kat_id\nWHERE m.qiymet > 2.4\nORDER BY k.ad, m.qiymet DESC;\n"},
  {"id": "sql-09-5", "lang": "sql", "level": 9, "title": "CROSS JOIN: bütün kombinasiyalar", "keywords": ["cross join", "kombinasiya", "cartesian product", "bütün cütlər", "декартово произведение", "ölçü və rəng", "hər biri ilə hər biri", "combinations"], "code": "CREATE TABLE olcu (ad TEXT);\nCREATE TABLE reng (ad TEXT);\nINSERT INTO olcu VALUES ('S'), ('M'), ('L');\nINSERT INTO reng VALUES ('ağ'), ('qara'), ('mavi');\n\nSELECT o.ad AS olcu, r.ad AS reng\nFROM olcu o CROSS JOIN reng r\nORDER BY o.ad, r.ad;\n\nSELECT COUNT(*) AS kombinasiya_sayi FROM olcu CROSS JOIN reng;\n"},
  {"id": "sql-10-1", "lang": "sql", "level": 10, "title": "LEFT JOIN", "keywords": ["left join", "sol birləşmə", "olmayanları tap", "sifarişi olmayan müştərilər", "левое соединение", "boş cavab", "null join", "hamısı və uyğunluq", "outer join"], "code": "CREATE TABLE musteri (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri_id INTEGER, mebleg REAL);\nINSERT INTO musteri VALUES (1, 'Aysel'), (2, 'Murad'), (3, 'Nigar'), (4, 'Zaur');\nINSERT INTO sifaris VALUES (1, 1, 50), (2, 1, 30), (3, 3, 75);\n\n-- Bütün müştərilər, sifarişi olmasa da\nSELECT m.ad, s.mebleg FROM musteri m LEFT JOIN sifaris s ON s.musteri_id = m.id ORDER BY m.id;\n\n-- Heç sifariş verməyənlər\nSELECT m.ad FROM musteri m LEFT JOIN sifaris s ON s.musteri_id = m.id WHERE s.id IS NULL;\n"},
  {"id": "sql-10-2", "lang": "sql", "level": 10, "title": "LEFT JOIN və COUNT", "keywords": ["left join count", "say sıfır", "hər kateqoriyada nə qədər", "sıfır olanlar da", "количество с нулем", "boş qruplar", "hesabat sıfırlarla"], "code": "CREATE TABLE sinif (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE telebe (id INTEGER PRIMARY KEY, ad TEXT, sinif_id INTEGER);\nINSERT INTO sinif VALUES (1, '9-A'), (2, '10-B'), (3, '11-C');\nINSERT INTO telebe VALUES (1, 'Aysel', 1), (2, 'Elvin', 1), (3, 'Nigar', 2);\n\nSELECT s.ad AS sinif, COUNT(t.id) AS telebe_sayi\nFROM sinif s LEFT JOIN telebe t ON t.sinif_id = s.id\nGROUP BY s.id\nORDER BY s.ad;\n"},
  {"id": "sql-10-3", "lang": "sql", "level": 10, "title": "Self join: işçi və rəhbər", "keywords": ["self join", "özünə birləşmə", "rəhbər", "manager", "işçi iyerarxiyası", "самосоединение", "employee manager", "ierarxiya", "kim kimə tabedir"], "code": "CREATE TABLE isci (id INTEGER PRIMARY KEY, ad TEXT, rehber_id INTEGER);\nINSERT INTO isci VALUES\n  (1, 'Murad', NULL), (2, 'Leyla', 1), (3, 'Zaur', 1), (4, 'Aysel', 2), (5, 'Elvin', 2);\n\nSELECT i.ad AS isci, COALESCE(r.ad, '(rəhbər yoxdur)') AS rehber\nFROM isci i\nLEFT JOIN isci r ON r.id = i.rehber_id\nORDER BY i.id;\n\nSELECT r.ad AS rehber, COUNT(*) AS tabe_olan\nFROM isci i JOIN isci r ON r.id = i.rehber_id\nGROUP BY r.id;\n"},
  {"id": "sql-10-4", "lang": "sql", "level": 10, "title": "Bir neçə LEFT JOIN ilə hesabat", "keywords": ["çoxlu left join", "hesabat", "report", "kurs hesabatı", "müştəri hesabatı", "join hesabat", "bütün əlaqələr", "нескольких соединений"], "code": "CREATE TABLE musteri (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri_id INTEGER, mebleg REAL);\nCREATE TABLE odenis (id INTEGER PRIMARY KEY, sifaris_id INTEGER, mebleg REAL);\nINSERT INTO musteri VALUES (1, 'Aysel'), (2, 'Murad'), (3, 'Nigar');\nINSERT INTO sifaris VALUES (1, 1, 100), (2, 1, 40), (3, 2, 80);\nINSERT INTO odenis VALUES (1, 1, 100), (2, 2, 20), (3, 3, 80);\n\nSELECT m.ad,\n  COUNT(DISTINCT s.id) AS sifaris_sayi,\n  COALESCE(SUM(DISTINCT s.mebleg), 0) AS sifaris_cemi,\n  COALESCE(SUM(o.mebleg), 0) AS odenilen\nFROM musteri m\nLEFT JOIN sifaris s ON s.musteri_id = m.id\nLEFT JOIN odenis o ON o.sifaris_id = s.id\nGROUP BY m.id;\n"},
  {"id": "sql-10-5", "lang": "sql", "level": 10, "title": "FULL JOIN əvəzinə UNION", "keywords": ["full join", "tam birləşmə", "hər iki tərəf", "outer join", "left union right", "полное соединение", "uyğun olmayanlar", "ortaq və fərqli"], "code": "CREATE TABLE a_sinif (ad TEXT);\nCREATE TABLE b_sinif (ad TEXT);\nINSERT INTO a_sinif VALUES ('Aysel'), ('Murad'), ('Nigar');\nINSERT INTO b_sinif VALUES ('Murad'), ('Elvin'), ('Nigar');\n\n-- Hər ikisində olanlar (ortaq)\nSELECT a.ad FROM a_sinif a JOIN b_sinif b ON a.ad = b.ad;\n-- Yalnız birində olanlar\nSELECT a.ad AS yalniz_a FROM a_sinif a LEFT JOIN b_sinif b ON a.ad = b.ad WHERE b.ad IS NULL;\nSELECT b.ad AS yalniz_b FROM b_sinif b LEFT JOIN a_sinif a ON a.ad = b.ad WHERE a.ad IS NULL;\n-- Hamısı\nSELECT ad FROM a_sinif UNION SELECT ad FROM b_sinif ORDER BY ad;\n"},
  {"id": "sql-11-1", "lang": "sql", "level": 11, "title": "Alt sorğu WHERE-də", "keywords": ["subquery", "alt sorğu", "nested query", "iç-içə sorğu", "подзапрос", "ortalamadan yuxarı", "sorğu içində sorğu", "scalar subquery"], "code": "CREATE TABLE isci (id INTEGER PRIMARY KEY, ad TEXT, maas REAL, shobe TEXT);\nINSERT INTO isci (ad, maas, shobe) VALUES\n  ('Murad', 1500, 'IT'), ('Leyla', 1800, 'IT'), ('Zaur', 1200, 'Satış'),\n  ('Aysel', 2000, 'Satış'), ('Elvin', 900, 'Mühasibat');\n\n-- Orta maaşdan çox alanlar\nSELECT ad, maas FROM isci WHERE maas > (SELECT AVG(maas) FROM isci) ORDER BY maas DESC;\n-- Ən yüksək maaşı alan\nSELECT ad FROM isci WHERE maas = (SELECT MAX(maas) FROM isci);\n"},
  {"id": "sql-11-2", "lang": "sql", "level": 11, "title": "IN ilə alt sorğu", "keywords": ["in subquery", "siyahı alt sorğu", "sifariş verən müştərilər", "exists", "не имеют заказов", "sifarişi olanlar", "in select", "exists və not exists"], "code": "CREATE TABLE musteri (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri_id INTEGER);\nINSERT INTO musteri VALUES (1, 'Aysel'), (2, 'Murad'), (3, 'Nigar'), (4, 'Zaur');\nINSERT INTO sifaris VALUES (1, 1), (2, 3), (3, 3);\n\nSELECT ad FROM musteri WHERE id IN (SELECT musteri_id FROM sifaris);\nSELECT ad FROM musteri WHERE id NOT IN (SELECT musteri_id FROM sifaris);\nSELECT ad FROM musteri m WHERE EXISTS (SELECT 1 FROM sifaris s WHERE s.musteri_id = m.id);\n"},
  {"id": "sql-11-3", "lang": "sql", "level": 11, "title": "FROM-da alt sorğu", "keywords": ["from subquery", "derived table", "müvəqqəti cədvəl", "вложенная таблица", "inline view", "qrup ortalamasının ortalaması", "iki mərhələli hesab"], "code": "CREATE TABLE satis (satici TEXT, mebleg REAL);\nINSERT INTO satis VALUES ('Aysel', 100), ('Aysel', 250), ('Murad', 80), ('Murad', 60), ('Nigar', 300), ('Nigar', 40);\n\nSELECT satici, cem FROM (\n  SELECT satici, SUM(mebleg) AS cem FROM satis GROUP BY satici\n) WHERE cem > 150\nORDER BY cem DESC;\n\nSELECT ROUND(AVG(cem), 2) AS saticilarin_orta_cemi FROM (SELECT SUM(mebleg) AS cem FROM satis GROUP BY satici);\n"},
  {"id": "sql-11-4", "lang": "sql", "level": 11, "title": "SELECT-də alt sorğu", "keywords": ["select içində alt sorğu", "correlated subquery", "əlaqəli alt sorğu", "hər sətir üçün", "коррелированный подзапрос", "ümumi cəmə nisbət", "sütun kimi alt sorğu"], "code": "CREATE TABLE telebe (id INTEGER PRIMARY KEY, ad TEXT, sinif TEXT, bal INTEGER);\nINSERT INTO telebe (ad, sinif, bal) VALUES\n  ('Aysel', 'A', 95), ('Elvin', 'A', 70), ('Nigar', 'B', 88), ('Murad', 'B', 92), ('Leyla', 'A', 82);\n\nSELECT ad, sinif, bal,\n  (SELECT ROUND(AVG(bal), 1) FROM telebe t2 WHERE t2.sinif = t1.sinif) AS sinif_orta,\n  bal - (SELECT AVG(bal) FROM telebe t2 WHERE t2.sinif = t1.sinif) AS ferq\nFROM telebe t1\nORDER BY sinif, bal DESC;\n"},
  {"id": "sql-11-5", "lang": "sql", "level": 11, "title": "Hər qrupda ən yüksək", "keywords": ["hər qrupda ən yüksək", "top per group", "max per group", "ən yüksək maaş şöbə üzrə", "наибольший в группе", "qrupda birinci", "sinifdə ən yaxşı"], "code": "CREATE TABLE isci (ad TEXT, shobe TEXT, maas REAL);\nINSERT INTO isci VALUES\n  ('Murad', 'IT', 1500), ('Leyla', 'IT', 1800), ('Zaur', 'Satış', 1200),\n  ('Aysel', 'Satış', 2000), ('Elvin', 'Mühasibat', 900), ('Nigar', 'Mühasibat', 1100);\n\nSELECT i.shobe, i.ad, i.maas\nFROM isci i\nWHERE i.maas = (SELECT MAX(maas) FROM isci WHERE shobe = i.shobe)\nORDER BY i.maas DESC;\n"},
  {"id": "sql-12-1", "lang": "sql", "level": 12, "title": "UNION və UNION ALL", "keywords": ["union", "union all", "birləşdir", "nəticələri birləşdir", "объединение запросов", "iki sorğu", "siyahıları qat", "birləşmə"], "code": "CREATE TABLE telebe (ad TEXT, sinif TEXT);\nCREATE TABLE muellim (ad TEXT, fenn TEXT);\nINSERT INTO telebe VALUES ('Aysel', '10-A'), ('Murad', '10-B');\nINSERT INTO muellim VALUES ('Leyla', 'riyaziyyat'), ('Murad', 'fizika');\n\nSELECT ad, 'tələbə' AS rol FROM telebe\nUNION\nSELECT ad, 'müəllim' FROM muellim\nORDER BY ad;\n\nSELECT ad FROM telebe UNION SELECT ad FROM muellim;       -- təkrarsız\nSELECT ad FROM telebe UNION ALL SELECT ad FROM muellim;   -- təkrarlarla\n"},
  {"id": "sql-12-2", "lang": "sql", "level": 12, "title": "INTERSECT və EXCEPT", "keywords": ["intersect", "except", "kəsişmə", "fərq", "set operations", "çoxluq əməliyyatları", "пересечение", "разность", "ortaq elementlər", "yalnız birində"], "code": "CREATE TABLE python_kurs (ad TEXT);\nCREATE TABLE sql_kurs (ad TEXT);\nINSERT INTO python_kurs VALUES ('Aysel'), ('Murad'), ('Nigar'), ('Elvin');\nINSERT INTO sql_kurs VALUES ('Murad'), ('Nigar'), ('Zaur');\n\nSELECT ad FROM python_kurs INTERSECT SELECT ad FROM sql_kurs;    -- hər ikisində\nSELECT ad FROM python_kurs EXCEPT SELECT ad FROM sql_kurs;       -- yalnız Python\nSELECT ad FROM sql_kurs EXCEPT SELECT ad FROM python_kurs;       -- yalnız SQL\n"},
  {"id": "sql-12-3", "lang": "sql", "level": 12, "title": "Hesabat sətirləri: cəmi sətri ilə", "keywords": ["cəmi sətri", "total row", "hesabat cəmi", "union cəm", "итоговая строка", "yekun sətir", "subtotal", "hesabatın sonuna cəmi əlavə et"], "code": "CREATE TABLE satis (mehsul TEXT, mebleg REAL);\nINSERT INTO satis VALUES ('Kitab', 120), ('Qələm', 30), ('Çanta', 210), ('Kitab', 80);\n\nSELECT mehsul, cem FROM (\n  SELECT mehsul, SUM(mebleg) AS cem, 0 AS sira FROM satis GROUP BY mehsul\n  UNION ALL\n  SELECT 'CƏMİ', SUM(mebleg), 1 FROM satis\n)\nORDER BY sira, cem DESC;\n"},
  {"id": "sql-12-4", "lang": "sql", "level": 12, "title": "Ən çox və ən az olanları birgə göstərmək", "keywords": ["ən çox ən az", "top bottom", "ən yaxşı ən pis", "birgə nəticə", "лучший и худший", "union limit", "rekord və minimum", "ekstremum"], "code": "CREATE TABLE kitab (ad TEXT, oxunma INTEGER);\nINSERT INTO kitab VALUES ('A', 340), ('B', 120), ('C', 980), ('D', 15), ('E', 560), ('F', 70);\n\nSELECT * FROM (SELECT 'ən çox oxunan' AS tip, ad, oxunma FROM kitab ORDER BY oxunma DESC LIMIT 1)\nUNION ALL\nSELECT * FROM (SELECT 'ən az oxunan', ad, oxunma FROM kitab ORDER BY oxunma ASC LIMIT 1);\n"},
  {"id": "sql-12-5", "lang": "sql", "level": 12, "title": "Cədvəl müqayisəsi: fərqləri tapmaq", "keywords": ["cədvəl müqayisəsi", "compare tables", "fərqləri tap", "diff", "сравнение таблиц", "dəyişən sətirlər", "köhnə və yeni", "version comparison"], "code": "CREATE TABLE qiymet_kohne (mehsul TEXT, qiymet REAL);\nCREATE TABLE qiymet_yeni (mehsul TEXT, qiymet REAL);\nINSERT INTO qiymet_kohne VALUES ('Alma', 2.0), ('Armud', 3.0), ('Süd', 2.2);\nINSERT INTO qiymet_yeni VALUES ('Alma', 2.5), ('Armud', 3.0), ('Pendir', 9.8);\n\nSELECT 'dəyişib' AS vəziyyət, k.mehsul, k.qiymet AS kohne, y.qiymet AS yeni\nFROM qiymet_kohne k JOIN qiymet_yeni y ON y.mehsul = k.mehsul AND y.qiymet <> k.qiymet\nUNION ALL\nSELECT 'silinib', mehsul, qiymet, NULL FROM qiymet_kohne WHERE mehsul NOT IN (SELECT mehsul FROM qiymet_yeni)\nUNION ALL\nSELECT 'yeni', mehsul, NULL, qiymet FROM qiymet_yeni WHERE mehsul NOT IN (SELECT mehsul FROM qiymet_kohne);\n"},
  {"id": "sql-13-1", "lang": "sql", "level": 13, "title": "FOREIGN KEY", "keywords": ["foreign key", "xarici açar", "əlaqə", "relation", "внешний ключ", "cədvəllər arası əlaqə", "references", "on delete cascade", "referential integrity"], "code": "PRAGMA foreign_keys = ON;\n\nCREATE TABLE muellif (id INTEGER PRIMARY KEY, ad TEXT NOT NULL);\nCREATE TABLE kitab (\n  id INTEGER PRIMARY KEY,\n  ad TEXT NOT NULL,\n  muellif_id INTEGER NOT NULL REFERENCES muellif(id) ON DELETE CASCADE\n);\n\nINSERT INTO muellif VALUES (1, 'Nizami'), (2, 'Füzuli');\nINSERT INTO kitab (ad, muellif_id) VALUES ('Xəmsə', 1), ('Leyli və Məcnun', 2), ('Divan', 2);\n-- INSERT INTO kitab (ad, muellif_id) VALUES ('Yetim kitab', 99);   -- olmayan müəllif: FOREIGN KEY xətası verərdi\n\nDELETE FROM muellif WHERE id = 2;   -- onun kitabları da silinir\nSELECT k.ad, m.ad AS muellif FROM kitab k JOIN muellif m ON m.id = k.muellif_id;\n"},
  {"id": "sql-13-2", "lang": "sql", "level": 13, "title": "Bir-çox əlaqə: sinif və tələbələr", "keywords": ["bir çox əlaqə", "one to many", "1-n", "один ко многим", "sinif tələbə", "ana və uşaq cədvəl", "parent child", "schema design"], "code": "PRAGMA foreign_keys = ON;\nCREATE TABLE sinif (id INTEGER PRIMARY KEY, ad TEXT UNIQUE NOT NULL);\nCREATE TABLE telebe (\n  id INTEGER PRIMARY KEY,\n  ad TEXT NOT NULL,\n  sinif_id INTEGER REFERENCES sinif(id)\n);\n\nINSERT INTO sinif (ad) VALUES ('9-A'), ('10-B');\nINSERT INTO telebe (ad, sinif_id) VALUES ('Aysel', 1), ('Elvin', 1), ('Nigar', 2), ('Murad', NULL);\n\nSELECT COALESCE(s.ad, '(sinifsiz)') AS sinif, GROUP_CONCAT(t.ad, ', ') AS telebeler, COUNT(*) AS say\nFROM telebe t LEFT JOIN sinif s ON s.id = t.sinif_id\nGROUP BY s.id;\n"},
  {"id": "sql-13-3", "lang": "sql", "level": 13, "title": "Çox-çox əlaqə: kurs və tələbə", "keywords": ["çox çox əlaqə", "many to many", "junction table", "ara cədvəl", "многие ко многим", "əlaqə cədvəli", "tag", "etiket", "bridge table"], "code": "PRAGMA foreign_keys = ON;\nCREATE TABLE yazi (id INTEGER PRIMARY KEY, basliq TEXT);\nCREATE TABLE etiket (id INTEGER PRIMARY KEY, ad TEXT UNIQUE);\nCREATE TABLE yazi_etiket (\n  yazi_id INTEGER REFERENCES yazi(id) ON DELETE CASCADE,\n  etiket_id INTEGER REFERENCES etiket(id) ON DELETE CASCADE,\n  PRIMARY KEY (yazi_id, etiket_id)\n);\n\nINSERT INTO yazi VALUES (1, 'SQL başlanğıc'), (2, 'JavaScript dərsi'), (3, 'Verilənlər bazası');\nINSERT INTO etiket (ad) VALUES ('proqramlaşdırma'), ('dərs'), ('baza');\nINSERT INTO yazi_etiket VALUES (1, 1), (1, 2), (1, 3), (2, 1), (2, 2), (3, 3);\n\nSELECT y.basliq, GROUP_CONCAT(e.ad, ', ') AS etiketler\nFROM yazi y JOIN yazi_etiket ye ON ye.yazi_id = y.id JOIN etiket e ON e.id = ye.etiket_id\nGROUP BY y.id;\n"},
  {"id": "sql-13-4", "lang": "sql", "level": 13, "title": "Normallaşdırma nümunəsi", "keywords": ["normallaşdırma", "normalization", "3nf", "bazanı düzgün qur", "нормализация", "sxem dizaynı", "təkrarı azalt", "database design", "düzgün sxem"], "code": "-- Pis dizayn: şəhər adı hər sətirdə təkrarlanır\nCREATE TABLE pis_sifaris (id INTEGER PRIMARY KEY, musteri TEXT, seher TEXT, mehsul TEXT, qiymet REAL);\nINSERT INTO pis_sifaris VALUES (1, 'Aysel', 'Bakı', 'Kitab', 12), (2, 'Aysel', 'Bakı', 'Qələm', 1.5), (3, 'Murad', 'Gəncə', 'Kitab', 12);\n\n-- Yaxşı dizayn: ayrı cədvəllər\nCREATE TABLE seher (id INTEGER PRIMARY KEY, ad TEXT UNIQUE);\nCREATE TABLE musteri (id INTEGER PRIMARY KEY, ad TEXT UNIQUE, seher_id INTEGER REFERENCES seher(id));\nCREATE TABLE mehsul (id INTEGER PRIMARY KEY, ad TEXT UNIQUE, qiymet REAL);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri_id INTEGER REFERENCES musteri(id), mehsul_id INTEGER REFERENCES mehsul(id));\n\nINSERT INTO seher (ad) SELECT DISTINCT seher FROM pis_sifaris;\nINSERT INTO musteri (ad, seher_id) SELECT DISTINCT p.musteri, s.id FROM pis_sifaris p JOIN seher s ON s.ad = p.seher;\nINSERT INTO mehsul (ad, qiymet) SELECT DISTINCT mehsul, qiymet FROM pis_sifaris;\nINSERT INTO sifaris (musteri_id, mehsul_id)\n  SELECT m.id, h.id FROM pis_sifaris p JOIN musteri m ON m.ad = p.musteri JOIN mehsul h ON h.ad = p.mehsul;\n\nSELECT m.ad AS musteri, s.ad AS seher, h.ad AS mehsul, h.qiymet\nFROM sifaris f JOIN musteri m ON m.id = f.musteri_id JOIN seher s ON s.id = m.seher_id JOIN mehsul h ON h.id = f.mehsul_id;\n"},
  {"id": "sql-13-5", "lang": "sql", "level": 13, "title": "ON DELETE SET NULL və ON UPDATE CASCADE", "keywords": ["on delete set null", "on update cascade", "silinəndə nə olsun", "referential actions", "внешний ключ действия", "ata silinəndə uşaq", "id dəyişəndə"], "code": "PRAGMA foreign_keys = ON;\nCREATE TABLE shobe (kod TEXT PRIMARY KEY, ad TEXT);\nCREATE TABLE isci (\n  id INTEGER PRIMARY KEY,\n  ad TEXT,\n  shobe_kod TEXT REFERENCES shobe(kod) ON DELETE SET NULL ON UPDATE CASCADE\n);\n\nINSERT INTO shobe VALUES ('IT', 'İnformasiya texnologiyaları'), ('SAT', 'Satış');\nINSERT INTO isci (ad, shobe_kod) VALUES ('Murad', 'IT'), ('Leyla', 'IT'), ('Zaur', 'SAT');\n\nUPDATE shobe SET kod = 'TEX' WHERE kod = 'IT';   -- işçilərin kodu da avtomatik dəyişir\nDELETE FROM shobe WHERE kod = 'SAT';             -- Zaur-un şöbəsi NULL olur\n\nSELECT i.ad, i.shobe_kod, s.ad AS shobe FROM isci i LEFT JOIN shobe s ON s.kod = i.shobe_kod;\n"},
  {"id": "sql-14-1", "lang": "sql", "level": 14, "title": "VIEW (görünüş)", "keywords": ["view", "görünüş", "create view", "виртуальная таблица", "saxlanmış sorğu", "hesabat görünüşü", "sorğunu adlandır", "view nədir"], "code": "CREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri TEXT, mebleg REAL, tarix TEXT);\nINSERT INTO sifaris (musteri, mebleg, tarix) VALUES\n  ('Aysel', 120, '2026-09-01'), ('Murad', 60, '2026-09-03'), ('Aysel', 90, '2026-09-10'), ('Nigar', 200, '2026-09-12');\n\nCREATE VIEW musteri_hesabati AS\nSELECT musteri, COUNT(*) AS say, SUM(mebleg) AS cem\nFROM sifaris GROUP BY musteri;\n\nSELECT * FROM musteri_hesabati ORDER BY cem DESC;\nINSERT INTO sifaris (musteri, mebleg, tarix) VALUES ('Murad', 500, '2026-09-20');\nSELECT * FROM musteri_hesabati WHERE cem > 400;   -- view həmişə təzə məlumat göstərir\n"},
  {"id": "sql-14-2", "lang": "sql", "level": 14, "title": "INDEX və EXPLAIN QUERY PLAN", "keywords": ["index", "indeks", "sürətləndir", "explain query plan", "индекс", "sorğu planı", "performans", "axtarışı sürətləndir", "create index"], "code": "CREATE TABLE log (id INTEGER PRIMARY KEY, istifadeci TEXT, hereket TEXT);\nWITH RECURSIVE say(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM say WHERE n < 1000)\nINSERT INTO log (istifadeci, hereket) SELECT 'u' || (n % 50), 'h' || (n % 7) FROM say;\n\nEXPLAIN QUERY PLAN SELECT * FROM log WHERE istifadeci = 'u7';   -- indeks yoxdur: SCAN\nCREATE INDEX idx_log_istifadeci ON log(istifadeci);\nEXPLAIN QUERY PLAN SELECT * FROM log WHERE istifadeci = 'u7';   -- indeks ilə: SEARCH\n\nSELECT COUNT(*) AS say FROM log WHERE istifadeci = 'u7';\n"},
  {"id": "sql-14-3", "lang": "sql", "level": 14, "title": "UNIQUE index və kompozit index", "keywords": ["unique index", "composite index", "kompozit indeks", "unikal indeks", "составной индекс", "çoxsütunlu indeks", "dublikatın qarşısı"], "code": "CREATE TABLE ders (id INTEGER PRIMARY KEY, sinif TEXT, gun TEXT, saat INTEGER, fenn TEXT);\nCREATE UNIQUE INDEX uq_cedvel ON ders(sinif, gun, saat);   -- eyni sinifdə eyni vaxta iki dərs olmaz\n\nINSERT INTO ders (sinif, gun, saat, fenn) VALUES ('9-A', 'bazar ertəsi', 1, 'riyaziyyat');\nINSERT INTO ders (sinif, gun, saat, fenn) VALUES ('9-A', 'bazar ertəsi', 2, 'fizika');\nINSERT OR IGNORE INTO ders (sinif, gun, saat, fenn) VALUES ('9-A', 'bazar ertəsi', 1, 'tarix');   -- rədd edilir\n\nSELECT * FROM ders;\nSELECT name, \"unique\" FROM pragma_index_list('ders');\n"},
  {"id": "sql-14-4", "lang": "sql", "level": 14, "title": "Sxemə baxmaq: sqlite_master", "keywords": ["sqlite_master", "sxem", "schema", "bazanın quruluşu", "cədvəllərin siyahısı", "схема базы", "pragma table_info", "list tables", "struktur"], "code": "CREATE TABLE musteri (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, email TEXT);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri_id INTEGER REFERENCES musteri(id), mebleg REAL);\nCREATE INDEX idx_sifaris_musteri ON sifaris(musteri_id);\nCREATE VIEW boyuk_sifaris AS SELECT * FROM sifaris WHERE mebleg > 100;\n\nSELECT type, name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type, name;\nSELECT name, type, \"notnull\" AS mecburi, pk FROM pragma_table_info('musteri');\nSELECT \"from\" AS sutun, \"table\" AS hedef_cedvel FROM pragma_foreign_key_list('sifaris');\n"},
  {"id": "sql-14-5", "lang": "sql", "level": 14, "title": "Müvəqqəti cədvəl", "keywords": ["temp table", "müvəqqəti cədvəl", "temporary", "временная таблица", "ara nəticə", "scratch", "müvəqqəti məlumat"], "code": "CREATE TABLE satis (id INTEGER PRIMARY KEY, mehsul TEXT, say INTEGER, qiymet REAL);\nINSERT INTO satis (mehsul, say, qiymet) VALUES ('Kitab', 5, 12), ('Qələm', 20, 1.5), ('Çanta', 2, 35), ('Dəftər', 15, 3);\n\nCREATE TEMP TABLE boyuk_satis AS\nSELECT mehsul, say * qiymet AS mebleg FROM satis WHERE say * qiymet >= 40;\n\nSELECT * FROM boyuk_satis ORDER BY mebleg DESC;\nSELECT SUM(mebleg) AS cem FROM boyuk_satis;\nDROP TABLE boyuk_satis;\n"},
  {"id": "sql-15-1", "lang": "sql", "level": 15, "title": "WITH (CTE)", "keywords": ["with", "cte", "common table expression", "ümumi cədvəl ifadəsi", "oxunaqlı sorğu", "общее табличное выражение", "müvəqqəti ad", "step by step query"], "code": "CREATE TABLE satis (satici TEXT, mebleg REAL);\nINSERT INTO satis VALUES ('Aysel', 100), ('Aysel', 250), ('Murad', 80), ('Murad', 60), ('Nigar', 300), ('Nigar', 40);\n\nWITH cemler AS (\n  SELECT satici, SUM(mebleg) AS cem FROM satis GROUP BY satici\n)\nSELECT satici, cem, ROUND(100.0 * cem / (SELECT SUM(cem) FROM cemler), 1) AS pay_faiz\nFROM cemler\nORDER BY cem DESC;\n"},
  {"id": "sql-15-2", "lang": "sql", "level": 15, "title": "Bir neçə CTE zənciri", "keywords": ["birdən çox cte", "cte zənciri", "chain of cte", "çoxmərhələli sorğu", "несколько cte", "step by step", "aralıq nəticə", "kohort"], "code": "CREATE TABLE telebe_bal (telebe TEXT, fenn TEXT, bal INTEGER);\nINSERT INTO telebe_bal VALUES\n  ('Aysel', 'A', 95), ('Aysel', 'B', 88), ('Elvin', 'A', 70), ('Elvin', 'B', 62),\n  ('Nigar', 'A', 85), ('Nigar', 'B', 90), ('Murad', 'A', 50), ('Murad', 'B', 58);\n\nWITH orta AS (\n  SELECT telebe, AVG(bal) AS orta_bal FROM telebe_bal GROUP BY telebe\n),\numumi AS (\n  SELECT AVG(orta_bal) AS umumi_orta FROM orta\n)\nSELECT o.telebe, ROUND(o.orta_bal, 1) AS orta_bal,\n  CASE WHEN o.orta_bal > u.umumi_orta THEN 'ortadan yuxarı' ELSE 'ortadan aşağı' END AS vəziyyət\nFROM orta o, umumi u\nORDER BY o.orta_bal DESC;\n"},
  {"id": "sql-15-3", "lang": "sql", "level": 15, "title": "CTE ilə UPDATE və DELETE", "keywords": ["cte update", "cte delete", "ən köhnə", "silmək üçün cte", "with delete", "dublikatları sil", "удаление дубликатов"], "code": "CREATE TABLE kontakt (id INTEGER PRIMARY KEY, email TEXT, ad TEXT);\nINSERT INTO kontakt (email, ad) VALUES\n  ('a@mail.az', 'Aysel'), ('b@mail.az', 'Murad'), ('a@mail.az', 'Aysel (təkrar)'), ('c@mail.az', 'Nigar'), ('b@mail.az', 'Murad (təkrar)');\n\nWITH saxlanan AS (SELECT MIN(id) AS id FROM kontakt GROUP BY email)\nDELETE FROM kontakt WHERE id NOT IN (SELECT id FROM saxlanan);\n\nSELECT * FROM kontakt ORDER BY id;\n"},
  {"id": "sql-15-4", "lang": "sql", "level": 15, "title": "Say seriyası düzəltmək", "keywords": ["generate series", "say seriyası", "ardıcıl ədədlər", "1 den 10", "числовая последовательность", "tarix siyahısı", "recursive cte numbers", "calendar", "təqvim"], "code": "-- 1-dən 10-a qədər\nWITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 10)\nSELECT i, i * i AS kvadrat FROM n;\n\n-- Oktyabr 2026 günləri\nWITH RECURSIVE gun(d) AS (\n  SELECT '2026-10-01' UNION ALL SELECT date(d, '+1 day') FROM gun WHERE d < '2026-10-07'\n)\nSELECT d, strftime('%w', d) AS hefte_gunu FROM gun;\n"},
  {"id": "sql-15-5", "lang": "sql", "level": 15, "title": "CTE ilə ən son qeyd", "keywords": ["ən son qeyd", "latest record", "son status", "последняя запись", "hər istifadəçinin son fəaliyyəti", "max tarix join", "row_number alternativ"], "code": "CREATE TABLE status_tarixce (id INTEGER PRIMARY KEY, sifaris INTEGER, status TEXT, vaxt TEXT);\nINSERT INTO status_tarixce (sifaris, status, vaxt) VALUES\n  (1, 'qəbul edildi', '2026-10-01 10:00'), (1, 'hazırlanır', '2026-10-01 12:00'), (1, 'çatdırıldı', '2026-10-02 09:00'),\n  (2, 'qəbul edildi', '2026-10-02 11:00'), (2, 'hazırlanır', '2026-10-02 15:00');\n\nWITH son AS (SELECT sifaris, MAX(vaxt) AS vaxt FROM status_tarixce GROUP BY sifaris)\nSELECT s.sifaris, s.status, s.vaxt\nFROM status_tarixce s JOIN son ON son.sifaris = s.sifaris AND son.vaxt = s.vaxt\nORDER BY s.sifaris;\n"},
  {"id": "sql-16-1", "lang": "sql", "level": 16, "title": "Rekursiv CTE: işçi iyerarxiyası", "keywords": ["recursive cte", "rekursiv sorğu", "ağac", "tree", "iyerarxiya", "рекурсивный запрос", "işçi ağacı", "rəhbər zənciri", "org chart", "səviyyə"], "code": "CREATE TABLE isci (id INTEGER PRIMARY KEY, ad TEXT, rehber_id INTEGER);\nINSERT INTO isci VALUES\n  (1, 'Murad (direktor)', NULL), (2, 'Leyla', 1), (3, 'Zaur', 1),\n  (4, 'Aysel', 2), (5, 'Elvin', 2), (6, 'Nigar', 4);\n\nWITH RECURSIVE agac(id, ad, seviyye, yol) AS (\n  SELECT id, ad, 0, ad FROM isci WHERE rehber_id IS NULL\n  UNION ALL\n  SELECT i.id, i.ad, a.seviyye + 1, a.yol || ' > ' || i.ad\n  FROM isci i JOIN agac a ON i.rehber_id = a.id\n)\nSELECT substr('      ', 1, seviyye * 2) || ad AS struktur, seviyye, yol FROM agac ORDER BY yol;\n"},
  {"id": "sql-16-2", "lang": "sql", "level": 16, "title": "Rekursiv CTE: faktorial və fibonaççi", "keywords": ["rekursiv hesablama", "factorial sql", "fibonacci sql", "ardıcıllıq sql", "рекурсия в sql", "ədədi ardıcıllıq", "recursive math", "qüvvətlər"], "code": "WITH RECURSIVE faktorial(n, deyer) AS (\n  SELECT 1, 1\n  UNION ALL\n  SELECT n + 1, deyer * (n + 1) FROM faktorial WHERE n < 10\n)\nSELECT n, deyer AS \"n!\" FROM faktorial;\n\nWITH RECURSIVE fib(i, a, b) AS (\n  SELECT 1, 0, 1\n  UNION ALL\n  SELECT i + 1, b, a + b FROM fib WHERE i < 15\n)\nSELECT group_concat(a, ', ') AS fibonacci FROM fib;\n"},
  {"id": "sql-16-3", "lang": "sql", "level": 16, "title": "Kateqoriya ağacı və alt kateqoriyalar", "keywords": ["kateqoriya ağacı", "category tree", "alt kateqoriya", "menyu ağacı", "дерево категорий", "bütün uşaqlar", "descendants", "nested set alternativ"], "code": "CREATE TABLE kateqoriya (id INTEGER PRIMARY KEY, ad TEXT, ata_id INTEGER);\nINSERT INTO kateqoriya VALUES\n  (1, 'Elektronika', NULL), (2, 'Telefonlar', 1), (3, 'Kompüterlər', 1),\n  (4, 'Noutbuklar', 3), (5, 'Masaüstü', 3), (6, 'Geyim', NULL), (7, 'Ayaqqabı', 6);\n\n-- Elektronikanın bütün alt kateqoriyaları\nWITH RECURSIVE alt(id, ad) AS (\n  SELECT id, ad FROM kateqoriya WHERE ad = 'Elektronika'\n  UNION ALL\n  SELECT k.id, k.ad FROM kateqoriya k JOIN alt a ON k.ata_id = a.id\n)\nSELECT ad FROM alt;\n\n-- 'Noutbuklar'dan yuxarıya doğru yol\nWITH RECURSIVE yuxari(id, ad, ata_id) AS (\n  SELECT id, ad, ata_id FROM kateqoriya WHERE ad = 'Noutbuklar'\n  UNION ALL\n  SELECT k.id, k.ad, k.ata_id FROM kateqoriya k JOIN yuxari y ON k.id = y.ata_id\n)\nSELECT group_concat(ad, ' < ') AS yol FROM yuxari;\n"},
  {"id": "sql-16-4", "lang": "sql", "level": 16, "title": "Qrafda yol tapmaq", "keywords": ["qraf sql", "graph sql", "yol tap", "şəhərlər arası yol", "путь в графе", "flight routes", "marşrut", "qonşu şəhərlər", "reachability"], "code": "CREATE TABLE yol (basla TEXT, bitir TEXT, km INTEGER);\nINSERT INTO yol VALUES\n  ('Bakı', 'Sumqayıt', 35), ('Bakı', 'Şamaxı', 120), ('Sumqayıt', 'Quba', 130),\n  ('Şamaxı', 'Şəki', 115), ('Quba', 'Qusar', 40);\n\nWITH RECURSIVE marsrut(durak, yol, km) AS (\n  SELECT 'Bakı', 'Bakı', 0\n  UNION ALL\n  SELECT y.bitir, m.yol || ' -> ' || y.bitir, m.km + y.km\n  FROM marsrut m JOIN yol y ON y.basla = m.durak\n)\nSELECT yol, km FROM marsrut ORDER BY km;\n"},
  {"id": "sql-16-5", "lang": "sql", "level": 16, "title": "Faiz ilə yığım hesabı", "keywords": ["mürəkkəb faiz", "compound interest", "əmanət", "deposit", "сложный процент", "ay-ay hesab", "kredit cədvəli", "loan schedule", "amortizasiya"], "code": "-- 1000 məbləğ, aylıq 2% artım, 12 ay\nWITH RECURSIVE ay(n, mebleg) AS (\n  SELECT 0, 1000.0\n  UNION ALL\n  SELECT n + 1, mebleg * 1.02 FROM ay WHERE n < 12\n)\nSELECT n AS ay, ROUND(mebleg, 2) AS mebleg FROM ay;\n\n-- 1200 borcu aylıq 100 ödəniş\nWITH RECURSIVE borc(ay, qaliq) AS (\n  SELECT 0, 1200 UNION ALL SELECT ay + 1, qaliq - 100 FROM borc WHERE qaliq > 0\n)\nSELECT * FROM borc;\n"},
  {"id": "sql-17-1", "lang": "sql", "level": 17, "title": "ROW_NUMBER, RANK, DENSE_RANK", "keywords": ["window function", "pəncərə funksiyaları", "row_number", "rank", "dense_rank", "оконные функции", "sıra nömrəsi", "reytinq", "sıralama"], "code": "CREATE TABLE oyunc (ad TEXT, komanda TEXT, xal INTEGER);\nINSERT INTO oyunc VALUES\n  ('Aysel', 'A', 90), ('Murad', 'A', 85), ('Nigar', 'B', 90), ('Elvin', 'B', 70), ('Zaur', 'A', 85), ('Leyla', 'B', 95);\n\nSELECT ad, komanda, xal,\n  ROW_NUMBER() OVER (ORDER BY xal DESC) AS sira,\n  RANK() OVER (ORDER BY xal DESC) AS rank,\n  DENSE_RANK() OVER (ORDER BY xal DESC) AS dense_rank\nFROM oyunc\nORDER BY xal DESC, ad;\n"},
  {"id": "sql-17-2", "lang": "sql", "level": 17, "title": "PARTITION BY ilə qrup üzrə sıra", "keywords": ["partition by", "qrup üzrə sıralama", "top n per group", "hər qrupda ilk 2", "топ в группе", "rank within group", "komanda daxilində"], "code": "CREATE TABLE satis (satici TEXT, shobe TEXT, mebleg REAL);\nINSERT INTO satis VALUES\n  ('Aysel', 'A', 500), ('Murad', 'A', 300), ('Nigar', 'A', 450),\n  ('Elvin', 'B', 200), ('Leyla', 'B', 800), ('Zaur', 'B', 600), ('Samir', 'B', 100);\n\nSELECT * FROM (\n  SELECT shobe, satici, mebleg,\n    RANK() OVER (PARTITION BY shobe ORDER BY mebleg DESC) AS shobe_ici_sira\n  FROM satis\n) WHERE shobe_ici_sira <= 2\nORDER BY shobe, shobe_ici_sira;\n"},
  {"id": "sql-17-3", "lang": "sql", "level": 17, "title": "Yığılan cəm və hərəkətli ortalama", "keywords": ["running total", "yığılan cəm", "moving average", "hərəkətli ortalama", "нарастающий итог", "kumulyativ", "cumulative sum", "window frame", "rows between"], "code": "CREATE TABLE gunluk (gun TEXT, satis REAL);\nINSERT INTO gunluk VALUES\n  ('2026-10-01', 100), ('2026-10-02', 150), ('2026-10-03', 90),\n  ('2026-10-04', 200), ('2026-10-05', 120), ('2026-10-06', 180);\n\nSELECT gun, satis,\n  SUM(satis) OVER (ORDER BY gun) AS yigilan_cem,\n  ROUND(AVG(satis) OVER (ORDER BY gun ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 1) AS son_3_gun_orta\nFROM gunluk;\n"},
  {"id": "sql-17-4", "lang": "sql", "level": 17, "title": "LAG və LEAD ilə dəyişikliyi tapmaq", "keywords": ["lag", "lead", "əvvəlki sətir", "növbəti sətir", "dəyişiklik", "фактор роста", "предыдущее значение", "artım faizi", "growth", "fərq əvvəlkindən"], "code": "CREATE TABLE ay_gelir (ay TEXT, gelir REAL);\nINSERT INTO ay_gelir VALUES ('2026-01', 1000), ('2026-02', 1200), ('2026-03', 900), ('2026-04', 1500), ('2026-05', 1500);\n\nSELECT ay, gelir,\n  LAG(gelir) OVER (ORDER BY ay) AS evvelki,\n  gelir - LAG(gelir) OVER (ORDER BY ay) AS ferq,\n  ROUND(100.0 * (gelir - LAG(gelir) OVER (ORDER BY ay)) / LAG(gelir) OVER (ORDER BY ay), 1) AS artim_faizi,\n  LEAD(gelir) OVER (ORDER BY ay) AS novbeti\nFROM ay_gelir;\n"},
  {"id": "sql-17-5", "lang": "sql", "level": 17, "title": "NTILE, FIRST_VALUE və faiz paylanması", "keywords": ["ntile", "first_value", "last_value", "percent_rank", "kvartil", "quartile", "процентиль", "bölgülər", "qrup bölgüsü", "sıra faizi"], "code": "CREATE TABLE telebe (ad TEXT, bal INTEGER);\nINSERT INTO telebe VALUES\n  ('A', 98), ('B', 91), ('C', 85), ('D', 80), ('E', 77), ('F', 70), ('G', 66), ('H', 60);\n\nSELECT ad, bal,\n  NTILE(4) OVER (ORDER BY bal DESC) AS dord_bir,\n  ROUND(PERCENT_RANK() OVER (ORDER BY bal), 2) AS faiz_sira,\n  FIRST_VALUE(ad) OVER (ORDER BY bal DESC) AS birinci,\n  bal - AVG(bal) OVER () AS ortadan_ferq\nFROM telebe\nORDER BY bal DESC;\n"},
  {"id": "sql-18-1", "lang": "sql", "level": 18, "title": "Tranzaksiya: COMMIT və ROLLBACK", "keywords": ["transaction", "tranzaksiya", "commit", "rollback", "транзакция", "bank köçürməsi", "ya hamısı ya heç nə", "atomic", "geri qaytar", "begin"], "code": "CREATE TABLE hesab (ad TEXT PRIMARY KEY, balans REAL CHECK (balans >= 0));\nINSERT INTO hesab VALUES ('Aysel', 500), ('Murad', 100);\n\nBEGIN;\nUPDATE hesab SET balans = balans - 200 WHERE ad = 'Aysel';\nUPDATE hesab SET balans = balans + 200 WHERE ad = 'Murad';\nCOMMIT;\nSELECT * FROM hesab;      -- köçürmə tamamlandı\n\nBEGIN;\nUPDATE hesab SET balans = balans - 50 WHERE ad = 'Aysel';\nROLLBACK;                 -- dəyişiklik ləğv edilir\nSELECT * FROM hesab;\n"},
  {"id": "sql-18-2", "lang": "sql", "level": 18, "title": "SAVEPOINT", "keywords": ["savepoint", "ara nöqtə", "rollback to", "hissəvi geri qaytarma", "точка сохранения", "nested transaction", "mərhələli əməliyyat"], "code": "CREATE TABLE sifaris (id INTEGER PRIMARY KEY, mehsul TEXT);\n\nBEGIN;\nINSERT INTO sifaris (mehsul) VALUES ('Kitab');\nSAVEPOINT s1;\nINSERT INTO sifaris (mehsul) VALUES ('Qələm');\nINSERT INTO sifaris (mehsul) VALUES ('Çanta');\nROLLBACK TO s1;           -- yalnız s1-dən sonrakılar geri qayıdır\nINSERT INTO sifaris (mehsul) VALUES ('Dəftər');\nCOMMIT;\n\nSELECT * FROM sifaris;\n"},
  {"id": "sql-18-3", "lang": "sql", "level": 18, "title": "Trigger: avtomatik audit qeydi", "keywords": ["trigger", "tetikleyici", "триггер", "audit log", "dəyişiklik tarixçəsi", "avtomatik qeyd", "after update", "log trigger", "izləmə"], "code": "CREATE TABLE mehsul (id INTEGER PRIMARY KEY, ad TEXT, qiymet REAL);\nCREATE TABLE qiymet_tarixce (mehsul_id INTEGER, kohne REAL, yeni REAL, vaxt TEXT);\n\nCREATE TRIGGER qiymet_deyisdi\nAFTER UPDATE OF qiymet ON mehsul\nWHEN OLD.qiymet <> NEW.qiymet\nBEGIN\n  INSERT INTO qiymet_tarixce VALUES (NEW.id, OLD.qiymet, NEW.qiymet, datetime('2026-10-03 12:00:00'));\nEND;\n\nINSERT INTO mehsul (ad, qiymet) VALUES ('Kitab', 12), ('Qələm', 1.5);\nUPDATE mehsul SET qiymet = 14 WHERE ad = 'Kitab';\nUPDATE mehsul SET qiymet = 14 WHERE ad = 'Kitab';    -- dəyişmir, qeyd düşmür\nUPDATE mehsul SET qiymet = 2 WHERE ad = 'Qələm';\n\nSELECT * FROM qiymet_tarixce;\n"},
  {"id": "sql-18-4", "lang": "sql", "level": 18, "title": "Trigger: anbar sayı", "keywords": ["anbar trigger", "stok", "inventory trigger", "ehtiyat", "склад", "sifariş sonrası say azalt", "stock update", "raise abort", "çatışmazlıq"], "code": "CREATE TABLE anbar (mehsul TEXT PRIMARY KEY, say INTEGER NOT NULL);\nCREATE TABLE satis (id INTEGER PRIMARY KEY, mehsul TEXT, say INTEGER);\nINSERT INTO anbar VALUES ('Kitab', 10), ('Qələm', 50);\n\nCREATE TRIGGER yoxla_say BEFORE INSERT ON satis\nWHEN (SELECT say FROM anbar WHERE mehsul = NEW.mehsul) < NEW.say\nBEGIN\n  SELECT RAISE(IGNORE);   -- sətir səssizcə atılır (xəta göstərmək üçün RAISE(ABORT, 'mesaj') işlədin)\nEND;\n\nCREATE TRIGGER azalt_say AFTER INSERT ON satis\nBEGIN\n  UPDATE anbar SET say = say - NEW.say WHERE mehsul = NEW.mehsul;\nEND;\n\nINSERT INTO satis (mehsul, say) VALUES ('Kitab', 4);\nINSERT INTO satis (mehsul, say) VALUES ('Kitab', 20);   -- kifayət qədər yoxdur, atılır\nSELECT * FROM anbar;\nSELECT * FROM satis;\n"},
  {"id": "sql-18-5", "lang": "sql", "level": 18, "title": "Trigger: son dəyişiklik vaxtı", "keywords": ["updated_at", "son dəyişiklik", "modified time", "дата изменения", "avtomatik tarix", "timestamp", "soft delete", "yumşaq silmə"], "code": "CREATE TABLE qeyd (\n  id INTEGER PRIMARY KEY,\n  metn TEXT,\n  silinib INTEGER DEFAULT 0,\n  deyisib TEXT DEFAULT '2026-10-03 09:00:00'\n);\nCREATE TRIGGER qeyd_yenilendi AFTER UPDATE ON qeyd\nBEGIN\n  UPDATE qeyd SET deyisib = '2026-10-03 18:30:00' WHERE id = NEW.id;\nEND;\n\nINSERT INTO qeyd (metn) VALUES ('Birinci'), ('İkinci');\nUPDATE qeyd SET metn = 'Birinci (düzəldilmiş)' WHERE id = 1;\nUPDATE qeyd SET silinib = 1 WHERE id = 2;      -- yumşaq silmə\n\nSELECT * FROM qeyd;\nSELECT * FROM qeyd WHERE silinib = 0;\n"},
  {"id": "sql-19-1", "lang": "sql", "level": 19, "title": "UPSERT: ON CONFLICT", "keywords": ["upsert", "on conflict", "insert or replace", "varsa yenilə yoxdursa əlavə et", "вставить или обновить", "sayğac artır", "merge", "dublikat konflikt"], "code": "CREATE TABLE ziyaret (sehife TEXT PRIMARY KEY, say INTEGER NOT NULL DEFAULT 0);\n\nINSERT INTO ziyaret (sehife, say) VALUES ('/ana', 1)\n  ON CONFLICT(sehife) DO UPDATE SET say = say + 1;\nINSERT INTO ziyaret (sehife, say) VALUES ('/ana', 1)\n  ON CONFLICT(sehife) DO UPDATE SET say = say + 1;\nINSERT INTO ziyaret (sehife, say) VALUES ('/haqqinda', 1)\n  ON CONFLICT(sehife) DO UPDATE SET say = say + 1;\nINSERT INTO ziyaret (sehife, say) VALUES ('/ana', 1)\n  ON CONFLICT(sehife) DO UPDATE SET say = say + 1;\n\nSELECT * FROM ziyaret ORDER BY say DESC;\n"},
  {"id": "sql-19-2", "lang": "sql", "level": 19, "title": "RETURNING", "keywords": ["returning", "əlavə edilən sətri qaytar", "insert returning", "update returning", "delete returning", "возврат строк", "id-ni geri al", "dəyişən sətirlər"], "code": "CREATE TABLE tapsiriq (id INTEGER PRIMARY KEY AUTOINCREMENT, ad TEXT, bitib INTEGER DEFAULT 0);\n\nINSERT INTO tapsiriq (ad) VALUES ('Dərs oxu'), ('Məşq et') RETURNING id, ad;\nUPDATE tapsiriq SET bitib = 1 WHERE ad = 'Məşq et' RETURNING id, ad, bitib;\nDELETE FROM tapsiriq WHERE bitib = 1 RETURNING id AS silinen_id;\nSELECT * FROM tapsiriq;\n"},
  {"id": "sql-19-3", "lang": "sql", "level": 19, "title": "JSON funksiyaları", "keywords": ["json", "json_extract", "json_object", "json_each", "json array", "json sütunu", "json in sql", "json oxu", "json sorğu", "json_group_array"], "code": "CREATE TABLE sifaris (id INTEGER PRIMARY KEY, melumat TEXT);\nINSERT INTO sifaris (melumat) VALUES\n  ('{\"musteri\": \"Aysel\", \"mehsullar\": [\"kitab\", \"qələm\"], \"toplam\": 25.5}'),\n  ('{\"musteri\": \"Murad\", \"mehsullar\": [\"çanta\"], \"toplam\": 35}');\n\nSELECT id, json_extract(melumat, '$.musteri') AS musteri, json_extract(melumat, '$.toplam') AS toplam FROM sifaris;\nSELECT s.id, j.value AS mehsul FROM sifaris s, json_each(s.melumat, '$.mehsullar') j;\nSELECT json_object('ad', 'Elvin', 'yas', 21, 'fenler', json_array('riyaziyyat', 'fizika')) AS obyekt;\nSELECT json_group_array(json_extract(melumat, '$.musteri')) AS musteriler FROM sifaris;\n"},
  {"id": "sql-19-4", "lang": "sql", "level": 19, "title": "Generated sütun", "keywords": ["generated column", "hesablanmış sütun", "avtomatik sütun", "вычисляемый столбец", "tam ad", "dərəcə sütunu", "stored virtual", "ağıllı sütun"], "code": "CREATE TABLE sexs (\n  ad TEXT,\n  soyad TEXT,\n  boy_sm REAL,\n  ceki_kq REAL,\n  tam_ad TEXT GENERATED ALWAYS AS (ad || ' ' || soyad) VIRTUAL,\n  bmi REAL GENERATED ALWAYS AS (ROUND(ceki_kq / ((boy_sm / 100.0) * (boy_sm / 100.0)), 1)) STORED\n);\n\nINSERT INTO sexs (ad, soyad, boy_sm, ceki_kq) VALUES ('Aysel', 'Əliyeva', 165, 55), ('Murad', 'Həsənov', 180, 85);\nSELECT tam_ad, bmi FROM sexs;\nUPDATE sexs SET ceki_kq = 80 WHERE ad = 'Murad';\nSELECT tam_ad, bmi FROM sexs;\n"},
  {"id": "sql-19-5", "lang": "sql", "level": 19, "title": "GROUP_CONCAT və ardıcıl mətn", "keywords": ["group_concat", "mətn birləşdir", "siyahı vergüllə", "string_agg", "объединение строк", "bir sətirdə göstər", "tags", "etiketlər", "concat group"], "code": "CREATE TABLE telebe (ad TEXT, sinif TEXT, fenn TEXT);\nINSERT INTO telebe VALUES\n  ('Aysel', '10-A', 'riyaziyyat'), ('Aysel', '10-A', 'fizika'), ('Elvin', '10-A', 'tarix'),\n  ('Nigar', '10-B', 'kimya'), ('Nigar', '10-B', 'riyaziyyat');\n\nSELECT sinif, GROUP_CONCAT(DISTINCT ad) AS telebeler FROM telebe GROUP BY sinif;\nSELECT ad, GROUP_CONCAT(fenn, ' | ') AS fennler, COUNT(*) AS say FROM telebe GROUP BY ad ORDER BY say DESC, ad;\nSELECT GROUP_CONCAT(DISTINCT fenn) AS butun_fennler FROM telebe;\n"},
  {"id": "sql-20-1", "lang": "sql", "level": 20, "title": "Kitabxana idarəetmə sistemi", "keywords": ["kitabxana", "library system", "kitab icarə", "mini layihə", "библиотека", "borrow return", "oxucu", "kitab verilməsi", "tətbiq", "project"], "code": "PRAGMA foreign_keys = ON;\nCREATE TABLE kitab (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, muellif TEXT, nusxe INTEGER NOT NULL DEFAULT 1);\nCREATE TABLE oxucu (id INTEGER PRIMARY KEY, ad TEXT NOT NULL);\nCREATE TABLE icare (\n  id INTEGER PRIMARY KEY,\n  kitab_id INTEGER NOT NULL REFERENCES kitab(id),\n  oxucu_id INTEGER NOT NULL REFERENCES oxucu(id),\n  verilib TEXT NOT NULL,\n  qaytarilib TEXT\n);\n\nINSERT INTO kitab VALUES (1, 'Əli və Nino', 'Qurban Səid', 2), (2, 'Dədə Qorqud', 'Xalq dastanı', 1), (3, 'Xəmsə', 'Nizami', 1);\nINSERT INTO oxucu VALUES (1, 'Aysel'), (2, 'Murad');\nINSERT INTO icare (kitab_id, oxucu_id, verilib, qaytarilib) VALUES\n  (1, 1, '2026-09-01', '2026-09-10'), (2, 1, '2026-09-15', NULL), (2, 2, '2026-09-20', NULL), (3, 2, '2026-09-25', NULL);\n\n-- Hazırda oxucudakı kitablar\nSELECT o.ad AS oxucu, k.ad AS kitab, i.verilib,\n  CAST(julianday('2026-10-03') - julianday(i.verilib) AS INTEGER) AS gun\nFROM icare i JOIN kitab k ON k.id = i.kitab_id JOIN oxucu o ON o.id = i.oxucu_id\nWHERE i.qaytarilib IS NULL ORDER BY gun DESC;\n\n-- Mövcud nüsxə sayı\nSELECT k.ad, k.nusxe - COUNT(i.id) AS mövcud\nFROM kitab k LEFT JOIN icare i ON i.kitab_id = k.id AND i.qaytarilib IS NULL\nGROUP BY k.id;\n"},
  {"id": "sql-20-2", "lang": "sql", "level": 20, "title": "Bank sistemi: hesablar və köçürmələr", "keywords": ["bank", "bank sistemi", "hesab köçürmə", "balans", "transfer", "банк", "mini layihə", "əməliyyat tarixçəsi", "ledger", "mühasibat"], "code": "CREATE TABLE hesab (id INTEGER PRIMARY KEY, sahib TEXT NOT NULL);\nCREATE TABLE emeliyyat (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  hesab_id INTEGER NOT NULL REFERENCES hesab(id),\n  mebleg REAL NOT NULL,\n  qeyd TEXT\n);\nINSERT INTO hesab VALUES (1, 'Aysel'), (2, 'Murad'), (3, 'Nigar');\n\n-- Hər emeliyyat müsbət (daxil olan) və ya mənfi (çıxan) məbləğdir\nINSERT INTO emeliyyat (hesab_id, mebleg, qeyd) VALUES\n  (1, 1000, 'maaş'), (2, 300, 'maaş'), (3, 500, 'maaş'),\n  (1, -200, 'Murada köçürmə'), (2, 200, 'Aysəldən köçürmə'),\n  (2, -50, 'qida'), (3, -120, 'kommunal');\n\nSELECT h.sahib, SUM(e.mebleg) AS balans, COUNT(*) AS emeliyyat_sayi\nFROM hesab h JOIN emeliyyat e ON e.hesab_id = h.id\nGROUP BY h.id ORDER BY balans DESC;\n\nSELECT h.sahib, e.mebleg, e.qeyd,\n  SUM(e.mebleg) OVER (PARTITION BY h.id ORDER BY e.id) AS cari_balans\nFROM emeliyyat e JOIN hesab h ON h.id = e.hesab_id\nWHERE h.sahib = 'Murad' ORDER BY e.id;\n"},
  {"id": "sql-20-3", "lang": "sql", "level": 20, "title": "Mağaza: məhsul, sifariş və hesabat", "keywords": ["mağaza", "online shop", "e-commerce", "internet mağaza", "sifariş sistemi", "магазин", "mini layihə", "satış hesabatı", "order items", "faktura"], "code": "CREATE TABLE mehsul (id INTEGER PRIMARY KEY, ad TEXT, qiymet REAL, kateqoriya TEXT);\nCREATE TABLE sifaris (id INTEGER PRIMARY KEY, musteri TEXT, tarix TEXT);\nCREATE TABLE sifaris_setri (sifaris_id INTEGER, mehsul_id INTEGER, say INTEGER);\n\nINSERT INTO mehsul VALUES (1, 'Noutbuk', 1500, 'texnika'), (2, 'Siçan', 25, 'texnika'), (3, 'Kitab', 12, 'kitab'), (4, 'Çanta', 60, 'aksesuar');\nINSERT INTO sifaris VALUES (1, 'Aysel', '2026-09-28'), (2, 'Murad', '2026-09-29'), (3, 'Aysel', '2026-10-01');\nINSERT INTO sifaris_setri VALUES (1, 1, 1), (1, 2, 2), (2, 3, 4), (2, 4, 1), (3, 3, 2), (3, 2, 1);\n\n-- Faktura\nSELECT s.id AS sifaris, s.musteri, SUM(ss.say * m.qiymet) AS cem\nFROM sifaris s JOIN sifaris_setri ss ON ss.sifaris_id = s.id JOIN mehsul m ON m.id = ss.mehsul_id\nGROUP BY s.id;\n\n-- Kateqoriya üzrə satış\nSELECT m.kateqoriya, SUM(ss.say) AS satilan, SUM(ss.say * m.qiymet) AS gelir\nFROM sifaris_setri ss JOIN mehsul m ON m.id = ss.mehsul_id\nGROUP BY m.kateqoriya ORDER BY gelir DESC;\n\n-- Ən çox alış edən müştəri\nSELECT s.musteri, SUM(ss.say * m.qiymet) AS cem FROM sifaris s\nJOIN sifaris_setri ss ON ss.sifaris_id = s.id JOIN mehsul m ON m.id = ss.mehsul_id\nGROUP BY s.musteri ORDER BY cem DESC LIMIT 1;\n"},
  {"id": "sql-20-4", "lang": "sql", "level": 20, "title": "Məktəb jurnalı", "keywords": ["məktəb jurnalı", "school journal", "tələbə qiymətləri", "jurnal", "школьный журнал", "sinif hesabatı", "davamiyyət", "attendance", "mini layihə", "qiymət cədvəli"], "code": "CREATE TABLE sinif (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE telebe (id INTEGER PRIMARY KEY, ad TEXT, sinif_id INTEGER REFERENCES sinif(id));\nCREATE TABLE fenn (id INTEGER PRIMARY KEY, ad TEXT);\nCREATE TABLE qiymet (telebe_id INTEGER, fenn_id INTEGER, bal INTEGER CHECK (bal BETWEEN 1 AND 10));\n\nINSERT INTO sinif VALUES (1, '9-A'), (2, '9-B');\nINSERT INTO telebe VALUES (1, 'Aysel', 1), (2, 'Elvin', 1), (3, 'Nigar', 2), (4, 'Murad', 2);\nINSERT INTO fenn VALUES (1, 'Riyaziyyat'), (2, 'Fizika'), (3, 'Tarix');\nINSERT INTO qiymet VALUES\n  (1, 1, 10), (1, 2, 9), (1, 3, 8), (2, 1, 6), (2, 2, 7), (2, 3, 9),\n  (3, 1, 8), (3, 2, 8), (3, 3, 10), (4, 1, 5), (4, 2, 6), (4, 3, 7);\n\n-- Hər şagirdin orta balı və sinif üzrə yeri\nSELECT s.ad AS sinif, t.ad AS telebe, ROUND(AVG(q.bal), 2) AS orta,\n  RANK() OVER (PARTITION BY s.id ORDER BY AVG(q.bal) DESC) AS sinifde_yeri\nFROM telebe t JOIN sinif s ON s.id = t.sinif_id JOIN qiymet q ON q.telebe_id = t.id\nGROUP BY t.id ORDER BY s.ad, sinifde_yeri;\n\n-- Fənn üzrə ən yüksək bal\nSELECT f.ad AS fenn, MAX(q.bal) AS en_yuksek, ROUND(AVG(q.bal), 1) AS orta FROM qiymet q JOIN fenn f ON f.id = q.fenn_id GROUP BY f.id;\n"},
  {"id": "sql-20-5", "lang": "sql", "level": 20, "title": "Rəy və reytinq sistemi", "keywords": ["reytinq", "rating", "rəy", "review", "rating system", "оценки и отзывы", "ulduz", "ortalama reytinq", "istifadəçi rəyi", "mini layihə"], "code": "CREATE TABLE film (id INTEGER PRIMARY KEY, ad TEXT, il INTEGER);\nCREATE TABLE rey (id INTEGER PRIMARY KEY, film_id INTEGER REFERENCES film(id), istifadeci TEXT, ulduz INTEGER CHECK (ulduz BETWEEN 1 AND 5), metn TEXT);\nINSERT INTO film VALUES (1, 'Sənədli film A', 2024), (2, 'Tarix filmi B', 2025), (3, 'Uşaq filmi C', 2023);\nINSERT INTO rey (film_id, istifadeci, ulduz, metn) VALUES\n  (1, 'Aysel', 5, 'Çox maraqlı'), (1, 'Murad', 4, 'Yaxşı'), (1, 'Nigar', 5, NULL),\n  (2, 'Aysel', 3, 'Orta'), (2, 'Elvin', 2, 'Zəif'), (3, 'Leyla', 4, 'Uşaqlar sevdi');\n\nSELECT f.ad, COUNT(r.id) AS rey_sayi, ROUND(AVG(r.ulduz), 2) AS orta_ulduz,\n  REPLACE(PRINTF('%*s', CAST(ROUND(AVG(r.ulduz)) AS INTEGER), ''), ' ', '*') AS ulduzlar\nFROM film f LEFT JOIN rey r ON r.film_id = f.id\nGROUP BY f.id ORDER BY orta_ulduz DESC;\n\nSELECT ulduz, COUNT(*) AS say FROM rey GROUP BY ulduz ORDER BY ulduz DESC;\n"},
];
